-- four (single-file build)
-- GENERATED by test/amalgamate.lua from four.lua + lib/*.lua — do not
-- edit this file; edit the modules and rebuild.
--
-- this file replaces dust/code/four/four.lua as a drop-in. the
-- SuperCollider engine is NOT inlined: lib/Engine_Four.sc must still
-- exist next to it — and exactly ONCE on the whole device. never create a
-- second folder with another copy of the .sc: a duplicate Engine_Four
-- class hangs EVERY norns script on "LOADING".

-- four: a 4-track sampler
-- record any sound, then
-- loop, stretch and grain
-- it on four tracks.
--
-- START
-- 1 plug a sound into the
--   norns input.
-- 2 press K2 to record.
--   press K2 again. your
--   take loops, clean.
-- 3 turn E1 to walk the
--   pages.
--
-- ON EVERY PAGE
-- E1    change the page
-- E2 E3 the two knobs
-- K2 K3 the two keys
--       (the foot of the
--       screen names them)
-- K1    hold for a second
--       pair of knobs
-- K1+E1 pick track 1 to 4
-- K1+K2 stop or start all
-- K1+K3 tap: all effects
--       off. hold: erase
--       what the page holds
--
-- KEYS
-- tap a key and it stays
-- on. hold it and it is on
-- only while you hold.
--
-- PAGES
-- TAKE   record a sound
--        and set its loop
-- VOICE  how the track
--        plays the sound:
--   PLAY   a clean loop
--   GRAIN  a cloud of
--          small pieces
--   WARP   slow or fast,
--          same pitch
--   PV     freeze, smear
--   CLOUD  texture
-- TRACKS the four tracks:
--        on, level, and
--        sends (hold K1)
-- TAPE   loop the whole
--        output
-- FILTER tone and drive
-- EFFECT two for a track:
--        chorus, flange,
--        wobble, reson,
--        ring, echo
-- DELAY  echo, shared
-- REVERB space, shared
-- MIX    the levels
-- PADS   8 slices to play
-- MOTION record a knob
--        move, set LFOs
-- SCENE  keep a sound,
--        call it back,
--        morph to it
--
-- GOOD TO KNOW
-- each track has its own
-- sound. pick a track with
-- K1+E1, then TAKE records
-- into it.
-- a fresh take plays dry.
-- you add the effects.
-- every knob maps to MIDI
-- in PARAMS.
-- a grid is welcome, and
-- never needed.
--
-- the full guide is in
-- README.md

-- -----------------------------------------------------------------------------
-- this file is the orchestrator: state + params + key/encoder handlers. the
-- rest lives in lib/ modules (script-internal, NOT norns engines): mfont (pixel
-- font), mtape (the softcut tape + the mix law), mdeck (the loop deck law),
-- minput (midi/keyboard notes), mgrid (grid surface), mmotion (the gesture
-- looper), mscenes (scenes, morph, orbit, the way back), mpages (the screen and
-- the wav file reader), mplugin (installs four's own SuperCollider plugin).
-- they share one `ctx` table and params are the single source of truth. the
-- plan: doc/plan.md. the history: doc/changelog.md.

engine.name = "Four"

-- bring-up diagnostics: load milestones in maiden. If "script file executed"
-- appears without "init() called", the engine died in alloc — check the SC tab.
print("four: script file executed")

local mu = require "musicutil"

local min, max = math.min, math.max

-- ============================================================================
-- state (shared with the lib/ modules through ctx)
-- ============================================================================

-- twelve stations, ordered by FAMILY so neighbours belong together:
-- the take (TAKE VOICE TRACKS) · the loop deck (TAPE) · the tone
-- (FILTER EFFECT DELAY REVERB) · the console (MIX) · the performance layer
-- (PADS MOTION SCENE). EROSION and ORBIT are no longer pages: erosion only
-- ever worked in PLAY mode, so its controls live on VOICE's PLAY face (the
-- alt pair, which was a redundant scan/pitch copy there); the orbit drives
-- the scene machinery, and its knobs live in PARAMS (orbit), its RUN switch
-- on the grid/PARAMS/MIDI. SCENE's alt pair picks the crossfader's A end.
-- The params are UNCHANGED (ids are never renamed), only their surfaces
-- moved.
local PAGES = {
  "TAKE", "VOICE", "TRACKS", "TAPE", "FILTER", "EFFECT", "DELAY", "REVERB",
  "MIX", "PADS", "MOTION", "SCENE",
}

local FPS = 15

local tape_arm_phase      -- head position when tape rec opened a pass; nil = none
local tape_arm_was        -- the loop that pass widened, put back if it is declined
local tape_arm_jumped     -- that pass moved the head to the tape's start (it plays forward)
local rec_open = false    -- an engine record pass is open (armed by a real 1)
local rec_wrapped = false -- that pass came round the end of its buffer
local rec_last = 0        -- ...read from the write head's last poll
local polls = {}
local redraw_clock
local beat_clock          -- ctx.on_beat, on every beat of the clock
local prev_midi_add, prev_midi_remove   -- norns' hot-plug callbacks, restored

-- ============================================================================
-- helpers
-- ============================================================================

local function clamp(x, lo, hi)
  if x < lo then return lo elseif x > hi then return hi else return x end
end

local function ptoggle(id)
  params:set(id, params:get(id) == 0 and 1 or 0)
end

local function pget(id, default)
  if params.lookup[id] then return params:get(id) end
  return default
end

-- current window edges (sorted) and span
-- (four) the take window is the FOCUSED track's: its own material and
-- its own window. ctx.focus_take rewrites WIN.
local WIN = { "pos_start", "pos_end" }
local function window_bounds()
  local a = pget(WIN[1], 0)
  local b = pget(WIN[2], 1)
  local lo, hi = min(a, b), max(a, b)
  return lo, hi, max(hi - lo, 0.001)
end

-- zoom-aware fine control: window/loop edge params scale their encoder
-- deltas by the current span, so steps shrink as the region tightens —
-- a wide-open window moves fast, a tight loop nudges by milliseconds.
-- (combined with the 0.002 quantum on these specs: ~10ms at the finest.)
-- every value other than "win" is the param-id prefix of a loop pair.
local FINE_IDS = { pos_start = "win", pos_end = "win",
                   loop_start = "loop", loop_end = "loop",
                   t2_pos_start = "t2_pos", t2_pos_end = "t2_pos",
                   t3_pos_start = "t3_pos", t3_pos_end = "t3_pos",
                   t4_pos_start = "t4_pos", t4_pos_end = "t4_pos" }

-- interpolate between two values of one param in its controlspec's WARPED
-- space (unmap, lerp, map): linear in the space the encoder moves in, so an
-- exponential param (cutoff, pitch) sweeps evenly. Returns the value and the
-- normalized position. The scene morph and the motion depth both blend
-- through here.
local function warped_lerp(cs, a, b, t)
  local na = clamp(cs:unmap(a), 0, 1)
  local tn = na + (clamp(cs:unmap(b), 0, 1) - na) * t
  return cs:map(tn), tn
end

local function fine_delta(id, d)
  local kind = FINE_IDS[id]
  if not kind then return d end
  local span
  if kind == "win" then
    local _, _, s = window_bounds()
    span = s
  else
    span = math.abs(pget(kind .. "_end", 1) - pget(kind .. "_start", 0))
  end
  return d * clamp(math.max(span, 0.001) * 4, 0.08, 1)
end

-- ============================================================================
-- ctx: the one table the lib/ modules see
-- ============================================================================
-- helpers and stable table refs are bound by each module at init; the
-- mutable scalars below are written here (polls, handlers, the clock) and
-- read by the modules each call.

local ctx = {
  -- wiring
  pget = pget, ptoggle = ptoggle, clamp = clamp,
  window_bounds = window_bounds, warped_lerp = warped_lerp,
  PAGES = PAGES, FPS = FPS,
  -- ui state
  page = 1,
  alt = false,               -- K1 held
  last_input = 0,            -- frame of the last key/encoder touch (idle dim)
  idle_dim = false,
  held = {},                 -- held[n] = true while key n is down (page-independent)
  frame = 0,                 -- redraw frame counter (drives the REC blink)
  flash_id = nil,            -- the param whose footer word swells (turning)
  flash_until = 0,
  -- engine/system signals
  play_phase = 0,            -- engine poll: normalized playhead in the buffer
  play_phase2 = 0,           -- the same for tracks 2 to 4 (four)
  play_phases = { 0, 0, 0, 0 },
  rec_phase = 0,             -- engine poll: normalized write-head position
  rec_arm_phase = 0,         -- write-head position when rec was armed
  rec_reset_at = nil,        -- the frame a new take put the write head at 0 (see head_poll)
  rec_poll_time = nil,       -- when the write head's last poll came (util.time)
  rec_amp = 0,               -- engine poll: amplitude of what's being written
  rec_waiting = false,       -- armed to start on sound, none heard yet (TAKE: WAIT)
  amp_in = { 0, 0 },         -- system polls: live input amplitude L/R
  amp_out = { 0, 0 },        -- system polls: output amplitude L/R
  cpu_high = false,          -- the load is near the limit: the header says CPU
  tape_phase = 0,            -- softcut phase event: tape head, normalized
  tape_heard = nil,          -- an open tape pass: has it heard a sound yet (nil: no pass)
  tape_quiet = 0,            -- frames of silence at the tape's source while it records
  tape_msg = nil,            -- what the last tape pass did, for TAPE to say
  -- display-model flags (mpages paints them)
  wave_any = false,          -- false until something audible lands in the buffer
  twave_any = false,
  -- normalized 0..1 high-water mark of buffer content worth saving (from frame
  -- 0): the take end at rec-stop, a loaded sample's length, or 1 when regen has
  -- filled the whole buffer. write_take bounds the PSET save to it. 0 = empty.
  take_len = 0,
  -- pad bank: 8 slice pads, per-pad type (0 grain / 1 slice), a screen
  -- cursor for standalone select/audition. shared by the PADS page + the
  -- MIDI/grid note routing (they map an incoming note to a pad index).
  -- SOUND-LOCKS: per-pad voice (0 grain / 1 slice) + pitch (semitones). the
  -- `pad_voice`/`pad_pitch` params are the cursor EDITOR (Elektron data-knob
  -- style — they read/write the pad under pad_cursor); these arrays hold the 8
  -- locks and ride the PSET (ctx.padlock_pset_*). note_on reads them per pad.
  pad_type = {},             -- per-pad voice (0 grain / 1 slice); every read is `or 0`
  pad_pitch = {},            -- per-pad pitch (semitones); every read is `or 0`
  pad_sync = false,          -- guard: syncing the editor params FROM the arrays
  pad_cursor = 0,
  pad_n = 8,
  pad_held = {},             -- voice id -> pad index while sounding
  pad_order = {},            -- the same ids in press order, for the steal below
}

local Mfont = (function()  -- inlined lib/mfont.lua
-- mfont: the 4x5 pixel font and every routine that sets type with it.
--
-- the font comes from the bitmap mockups and is drawn rect-by-rect so the
-- device renders exactly what the bitmaps promised. rows top->bottom,
-- '1' = lit.

local floor = math.floor
local sbyte = string.byte

local FONT = {
  A = { "0110", "1001", "1111", "1001", "1001" },
  B = { "1110", "1001", "1110", "1001", "1110" },
  C = { "0111", "1000", "1000", "1000", "0111" },
  D = { "1110", "1001", "1001", "1001", "1110" },
  E = { "1111", "1000", "1110", "1000", "1111" },
  F = { "1111", "1000", "1110", "1000", "1000" },
  G = { "0111", "1000", "1011", "1001", "0111" },
  H = { "1001", "1001", "1111", "1001", "1001" },
  I = { "111", "010", "010", "010", "111" },
  J = { "0011", "0001", "0001", "1001", "0110" },
  K = { "1001", "1010", "1100", "1010", "1001" },
  L = { "1000", "1000", "1000", "1000", "1111" },
  M = { "10001", "11011", "10101", "10001", "10001" },
  N = { "1001", "1101", "1011", "1001", "1001" },
  O = { "0110", "1001", "1001", "1001", "0110" },
  P = { "1110", "1001", "1110", "1000", "1000" },
  Q = { "0110", "1001", "1001", "1010", "0101" },
  R = { "1110", "1001", "1110", "1010", "1001" },
  S = { "0111", "1000", "0110", "0001", "1110" },
  T = { "111", "010", "010", "010", "010" },
  U = { "1001", "1001", "1001", "1001", "0110" },
  V = { "101", "101", "101", "101", "010" },
  W = { "10001", "10001", "10101", "11011", "10001" },
  X = { "101", "101", "010", "101", "101" },
  Y = { "101", "101", "010", "010", "010" },
  Z = { "1111", "0001", "0110", "1000", "1111" },
  ["0"] = { "0110", "1001", "1011", "1101", "0110" },
  ["1"] = { "010", "110", "010", "010", "111" },
  ["2"] = { "1110", "0001", "0110", "1000", "1111" },
  ["3"] = { "1110", "0001", "0110", "0001", "1110" },
  ["4"] = { "1001", "1001", "1111", "0001", "0001" },
  ["5"] = { "1111", "1000", "1110", "0001", "1110" },
  ["6"] = { "0111", "1000", "1110", "1001", "0110" },
  ["7"] = { "1111", "0001", "0010", "0100", "0100" },
  ["8"] = { "0110", "1001", "0110", "1001", "0110" },
  ["9"] = { "0110", "1001", "0111", "0001", "1110" },
  ["."] = { "0", "0", "0", "0", "1" },
  ["-"] = { "000", "000", "111", "000", "000" },
  ["+"] = { "000", "010", "111", "010", "000" },
  ["="] = { "000", "111", "000", "111", "000" },
  [":"] = { "0", "1", "0", "1", "0" },
  ["/"] = { "001", "001", "010", "100", "100" },
  ["%"] = { "11001", "11010", "00100", "01011", "10011" },
  ["<"] = { "001", "010", "100", "010", "001" },
  [">"] = { "100", "010", "001", "010", "100" },
  -- the sharp of a note name (the RESON effect's note: C#3)
  ["#"] = { "01010", "11111", "01010", "11111", "01010" },
  [" "] = { "00", "00", "00", "00", "00" },
}

-- byte-indexed glyph + advance tables, built once: text draws every frame,
-- and a byte walk allocates nothing (per-char gmatch/sub costs an iterator
-- or a string per call). lua patterns are byte-based, so bytes match them.
local FONT_B, FONT_ADV = {}, {}
for b = 0, 255 do
  local ch = string.char(b)
  local g = FONT[ch] or FONT[ch:upper()] or FONT[" "]
  FONT_B[b] = g
  FONT_ADV[b] = #g[1] + 1
end

local function text_w(str, sc)
  local w = 0
  for i = 1, #str do w = w + FONT_ADV[sbyte(str, i)] * sc end
  return w - sc
end

-- draw a pixel-font string at (x,y) top-left, scale sc, brightness lvl
local function ptext(str, x, y, sc, lvl)
  screen.level(lvl)
  local cx = x
  for i = 1, #str do
    local b = sbyte(str, i)
    local g = FONT_B[b]
    for r = 1, 5 do
      local row = g[r]
      for c = 1, #row do
        if sbyte(row, c) == 49 then  -- 49 = "1"
          screen.rect(cx + (c - 1) * sc, y + (r - 1) * sc, sc, sc)
        end
      end
    end
    cx = cx + FONT_ADV[b] * sc
  end
  screen.fill()
  return cx - x - sc
end

local function ptext_c(str, cx, y, sc, lvl)
  ptext(str, floor(cx - text_w(str, sc) / 2 + 0.5), y, sc, lvl)
end

local function ptext_r(str, rx, y, sc, lvl)
  ptext(str, rx - text_w(str, sc), y, sc, lvl)
end

-- inverted chip (the ALT tag / mode badge from the mockups)
local function chip(str, x, y)
  local w = text_w(str, 1) + 5
  screen.level(15)
  screen.rect(x, y, w, 9)
  screen.fill()
  ptext(str, x + 3, y + 2, 1, 0)
  return w
end

return {
  text_w = text_w,
  ptext = ptext,
  ptext_c = ptext_c,
  ptext_r = ptext_r,
  chip = chip,
}

end)()
local Mtape = (function()  -- inlined lib/mtape.lua
-- mtape: every softcut touch — the TAPE path's plumbing, the eng<>tape mix,
-- and the tape audio halves of PSET save/load/delete.

local sc = require "softcut"  -- the TAPE path: parallel ADC tap, own CPU core

local TAPE_LEN = 60  -- seconds of softcut buffer used by the tape loop

local C     -- shared ctx, bound at init
local pget
local D     -- the deck module (lib/mdeck), handed in at init — `include` has
            -- no module cache, so including it here would build a SECOND
            -- instance with its own deck list and the phase/pset walks would
            -- split across the two

-- the tape as a DECK DESCRIPTOR: the shape mdeck builds, but NOT registered
-- in Mdeck.decks — its level law (the MIX crossfade in gains()), its pset
-- files, its phase events and its lifecycle stay this module's own. What it
-- borrows is the deck MECHANICS: rate and direction, rec/pre/freeze gating,
-- the loop bounds with the 100ms floor held inside the region, and the
-- region-scoped clear. Those laws existed twice, verbatim, and had already
-- drifted once before a review caught it; now they exist once.
local TAPE = {
  id = "tape", name = "TAPE", va = 1, vb = 2, from = 0, len = TAPE_LEN,
  alone = true,   -- no other deck is in softcut's buffer (Mdeck.zero)
  pre_default = 0,   -- classic tape: REPLACE unless tape_pre is raised
  keymap = { rec = "tape_rec", rate = "tape_rate", reverse = "tape_reverse",
             pre = "tape_pre", freeze = "tape_freeze", fade = "tape_fade",
             start = "loop_start", ["end"] = "loop_end" },
  -- display fields, unused here (the tape picture lives in mpages as twave)
  wave = {}, wave_bin = 0, any = false, phase = 0, gen = 0,
}

-- the descriptor is exported for the parts of the deck law that READ a deck
-- (its material extent); everything that writes goes through the functions
-- below
local M = { TAPE_LEN = TAPE_LEN, deck = TAPE }

function M.init(ctx, deckmod)
  C = ctx
  pget = ctx.pget
  D = deckmod
end

-- THE gain law: `mix` crossfades SC engine <-> tape (a plateau — center keeps
-- both at full trim), out_level masters both, stop_all chokes both. returns
-- eng_gain, tape_gain, master_out. update_mix sends it and the MIX page draws
-- it, so the picture reads from the one law instead of mirroring it.
function M.gains()
  local mixv = pget("mix", 0.5)
  local out = pget("out_level", 1) * (1 - pget("stop_all", 0))
  return pget("sc_level", 1) * math.min(1, 2 * (1 - mixv)) * out,
    pget("cut_level", 1) * math.min(1, 2 * mixv) * out,
    out
end

-- levels slew, so stop/start are click-free and START restores the exact mix
function M.update_mix()
  local sc_l, tp_l = M.gains()
  if engine.level then engine.level(sc_l) end
  sc.level(1, tp_l)
  sc.level(2, tp_l)
end

-- the deck mechanics, delegated (see the TAPE descriptor above). When they
-- were folded in, the softcut command stream over a state matrix (rates,
-- reverse, rec x freeze x pre, five loop shapes, clear) was captured before
-- and after and byte-diffed empty. The seam has gone through the same law
-- since: one fade writer, capped at a quarter of the loop.
--
-- What is NOT shared, and why. Volume, preset files, playhead position and
-- drawing stay here, because they really are the tape's own.
--
-- The loop-pedal behaviour is a different matter. mdeck has a version of it
-- (arm_loop / close_loop) and the tape has its own, written out by hand in
-- the tape_rec action in four.lua. That IS a duplicate, left in place on
-- purpose: the tape is one of the few parts of this instrument confirmed
-- working on real hardware, and merging it would also mean keeping
-- TAPE.phase up to date, which nothing does today. It waits for the same
-- device session as the rest of the merge.
--
-- The two now agree that stopping a recording may only re-cut the loop if
-- starting it opened one, that a pass too short to be a loop gives back the
-- loop it widened, and both move their
-- edges through D.set_loop. Since the forty-eighth change both also start a
-- new loop at the start of the tape (the region) when it plays forward, and
-- both keep the whole of it when the pass comes round its end. The jump, the
-- trust in a report after it and the wrap mark are mdeck's (D.jump, D.trust).
-- Two things still differ:
--   * the shortest recording the tape accepts is measured against the whole
--     tape; mdeck measures 100ms against the deck's own region
--   * mdeck checks which way the playhead was moving, so a deck playing
--     backwards closes its loop correctly. The tape does not.
-- If you change one of them, change both.
function M.update_tape_rate() D.update_rate(TAPE) end
function M.update_tape_rec() D.update_rec(TAPE) end
function M.update_tape_loop() D.update_loop(TAPE) end
-- Move both loop edges, in whichever order avoids leaving the start past the
-- end in between. See D.set_loop: getting it backwards makes the playhead jump.
function M.set_loop(lo, hi) D.set_loop(TAPE, lo, hi) end

-- Put both playheads at a position given as 0 to 1 across the tape. Stopping
-- a recording uses this to drop the head at the start of what was just
-- played, so it loops back straight away. Through the deck law: two
-- copies of "put the head here" is how the loop maths drifted apart before.
function M.jump_to(pos)
  D.jump(TAPE, pos)
  -- the head is there now. softcut's next reports are checked by D.trust in
  -- the phase handler, so a late one from the old place cannot undo this.
  C.tape_phase = math.min(math.max(pos, 0), 1)
end

-- does the tape play forward? The record action asks before it moves the head.
function M.forward() return D.forward(TAPE) end

-- the seam, through the deck law: capped at a quarter of the loop, so a long
-- fade on a short loop cannot leave the tape spending all its time fading
-- (a raw write here bypassed the cap the loop updates apply)
function M.set_fade() D.update_fade(TAPE) end

-- The whole buffer: the tape is alone in it (Mdeck.zero). (Mdeck.clear also resets the descriptor's unused
-- display fields — harmless; the tape picture is mpages' twave.)
function M.clear_buffer()
  D.clear(TAPE)
end

-- the tape's RECORD SOURCE (cut_source): 0 = DRY (the
-- raw ADC tap) .. 1 = WET (the engine's post-FX output — filter/drive/delay/
-- reverb). the two router sends SUM at the shared softcut input, so a blend
-- prints part raw + part processed and the tape becomes a resample / print
-- stage. NO runaway: the engine reads only the ADC bus (context.in_b), never
-- softcut, so eng -> cut is a one-way edge. The default is 1 (WET): a pass
-- records what four plays. At 0 it records the line input alone.
function M.set_source(v)
  audio.level_adc_cut(1 - v)   -- dry input tap
  audio.level_eng_cut(v)       -- processed engine output
end

function M.init_tape()
  M.set_source(pget("cut_source", 1))   -- dry/processed record source
  audio.level_cut(1)       -- softcut master out: persists across scripts, force up
  D.zero(TAPE)
  for v = 1, 2 do
    sc.enable(v, 1)
    sc.buffer(v, v)
    sc.pan(v, v == 1 and -1 or 1)
    sc.play(v, 1)
    sc.loop(v, 1)
    sc.position(v, 0)
    sc.level_slew_time(v, 0.05)
    sc.rate_slew_time(v, 0.05)
    -- force the filter sections fully open: their defaults can mute the voice
    sc.pre_filter_dry(v, 1.0)
    sc.pre_filter_lp(v, 0.0)
    sc.post_filter_dry(v, 1.0)
    sc.post_filter_lp(v, 0.0)
    for ch = 1, 2 do
      sc.level_input_cut(ch, v, (ch == v) and 1.0 or 0.0)
    end
  end
  M.update_tape_rate()
  M.update_tape_rec()
  M.update_tape_loop()     -- also sends the (capped) seam
  M.update_mix()
  -- tape head position events drive the TAPE page needle AND the loop
  -- snap points — 25ms quant keeps snapped loops tight (0.1 was audible)
  sc.phase_quant(1, 0.025)
  -- ONE softcut phase handler exists, and it lives here.
  sc.event_phase(function(v, pos)
    if v == 1 then
      local ph = pos / TAPE_LEN
      -- a report from the place the head left before a jump is dropped, and
      -- a head that came round the tape's end is noted (TAPE.wrapped)
      if not D.trust(TAPE, ph, C.tape_phase) then return end
      C.tape_phase = ph
      D.settle_rec(TAPE)
      -- the written stretch, from the 25ms phase events
      if pget("tape_rec", 0) == 1 and pget("tape_freeze", 0) == 0 then
        D.track_extent(TAPE, C.tape_phase)
      end
    end
  end)
  sc.poll_start_phase()
end

-- PSETs persist the tape audio too: SAVE writes the softcut buffers
-- (L=buf1, R=buf2, matching init_tape's routing) next to the pset; LOAD
-- reads them back, DELETE cleans up.
local function path_for(number)
  return norns.state.data .. "tape-" .. number .. ".wav"
end

function M.pset_write(number)
  -- like the take (take_pset_write): an untouched tape must not dump 60s of
  -- stereo silence per save, and a cleared one must not resurrect old audio
  -- on load — an empty save deletes the stale wav instead.
  if C.twave_any then
    sc.buffer_write_stereo(path_for(number), 0, D.save_secs(TAPE))
  else
    M.pset_delete(number)
  end
end

function M.pset_read(number)
  local path = path_for(number)
  if util.file_exists(path) then
    D.zero(TAPE)   -- the save may hold only the start
    sc.buffer_read_stereo(path, 0, 0, TAPE_LEN)
    C.twave_any = true
    D.restored_extent(TAPE, path)
    -- repaint the strip from the wav we just restored: lua cannot read the
    -- softcut buffer, so without this the loop played under a blank picture
    if C.repaint_twave then C.repaint_twave(path, TAPE_LEN) end
  else
    -- NO wav means the pset was saved with an EMPTY tape (pset_write deletes
    -- the file in that case, precisely so old audio cannot resurrect). Leaving
    -- the softcut buffer alone let it resurrect anyway — from the live buffer
    -- instead of from disk, which is the same failure by another route. An
    -- empty tape in the pset means an empty tape after loading it.
    M.clear_buffer()
    if C.clear_twave then C.clear_twave() end   -- wipes the picture + twave_any
  end
end

function M.pset_delete(number)
  os.remove(path_for(number))
end

function M.cleanup()
  sc.poll_stop_phase()
  audio.level_eng_cut(0)   -- don't leak a processed-source route to the next script
  audio.level_adc_cut(1)   -- ...and give the next script the stock ADC tap back
end

return M

end)()
local Mdeck = (function()  -- inlined lib/mdeck.lua
-- mdeck: a loop deck on a softcut voice pair.
--
-- One of these is a track: its own slice of the softcut buffer, its own loop
-- points, rate, direction and overdub. Several run at once for almost nothing,
-- because softcut is a separate audio core.
--
-- The instrument builds none with M.new today: the two layer decks (lay1,
-- lay2) are gone, the four engine tracks replaced them. The tape is the one
-- deck, and test/test_deck.lua builds its own to drive the law.
--
-- What a deck CANNOT do is granulate, warp or spectrally stretch. That is the
-- engine's buffer and the engine's voice. A deck is a loop.
--
-- The tape (lib/mtape.lua) borrows these mechanics through a keymapped
-- descriptor: rate, rec gating, loop bounds, the seam, clear and jump are
-- this module's. Its level law, pset files, phase events and its own
-- loop-pedal law stay in mtape and four.lua (see the note there).

local sc = require "softcut"

local C, pget, clamp

local M = {}

-- every deck built, in creation order, so the shared plumbing (the phase
-- dispatcher, the master level, cleanup) can walk them
M.decks = {}

-- ---------------------------------------------------------------------------
-- construction
-- ---------------------------------------------------------------------------
-- `o` = { id, name, va, vb, from, len, bins }
--   id       param prefix, e.g. "dk1" -> dk1_rec, dk1_level, ...
--   va, vb   the softcut voice pair (lower = left, upper = right)
--   from     where this deck's region starts, in seconds into the buffer
--   len      how long the region is, in seconds
-- One more field exists only while a recording is in progress: `arm_phase`,
-- where the playhead was when recording started. Its absence is what means
-- "nothing is being recorded", which is what close_loop checks, so it is
-- deliberately not set up here.
function M.new(o)
  local d = {
    id = o.id, name = o.name,
    va = o.va, vb = o.vb,
    from = o.from, len = o.len,
    phase = 0,          -- 0..1 within the region, from the softcut poll
    any = false,        -- has audio been recorded into it?
    wave = {},          -- the picture, painted as the head passes (o.bins bins)
    wave_bin = 0,
    gen = 0,            -- bumped by anything that replaces the material, so a
                        -- load that lands late can tell
    -- mat_lo / mat_hi: the stretch of the region that holds material (0..1),
    -- nil when there is none. Kept by track_extent, read through M.extent.
  }
  for i = 1, (o.bins or 128) do d.wave[i] = 0 end
  M.decks[#M.decks + 1] = d
  return d
end

-- a param id for this deck: p(d, "rec") -> "dk1_rec". A deck may carry a
-- `keymap` overriding the scheme — the TAPE deck's ids predate the prefix
-- naming (loop_start, tape_pre, ...) and ids are never renamed, so the map
-- is how it borrows these mechanics without touching its params.
local function p(d, k)
  local km = d.keymap
  return (km and km[k]) or (d.id .. "_" .. k)
end
M.p = p

local function get(d, k, dflt) return pget(p(d, k), dflt) end

-- both voices, same setting (the deck is stereo: lower = L, upper = R)
local function both(d, fn) fn(d.va); fn(d.vb) end

-- ---------------------------------------------------------------------------
-- the softcut side
-- ---------------------------------------------------------------------------

-- LEVEL folds in the master and the global STOP, exactly like the engine and
-- tape decks do — one key silences everything that makes sound, with no
-- exceptions and no deck that forgot.
--
-- `play` silences the deck by LEVEL rather than stopping its head, and that is
-- the point: two decks at different rates are only in a drifting relationship
-- while both heads keep moving. Stopping one and restarting it would snap it
-- back to its loop start and lose the phase against the other. The page says
-- MUTE, not STOP, because that is what it does.
function M.update_level(d)
  -- the master fold is computed here rather than read from C.mix_gains ON
  -- PURPOSE: this module stays drivable standalone (test/test_deck.lua stubs
  -- a bare ctx), and the two-factor fold is the whole overlap
  local out = pget("out_level", 1) * (1 - pget("stop_all", 0))
  local lv = get(d, "level", 0.8) * out * (get(d, "play", 1) == 1 and 1 or 0)
  both(d, function(v) sc.level(v, lv) end)
end

function M.update_rate(d)
  -- the global STOP halts the head, not just the level (true stop: START
  -- resumes from the exact spot). every deck stops AS ONE, so their relative
  -- drift survives; MUTE (play = 0) alone keeps the head moving, unchanged.
  local r = get(d, "rate", 1) * (get(d, "reverse", 0) == 1 and -1 or 1)
    * (1 - pget("stop_all", 0))
  both(d, function(v) sc.rate(v, r) end)
end

-- rec gates capture; `pre` is what survives a pass. pre 1 = OVERDUB (stack),
-- pre 0 = REPLACE. A deck defaults to overdub
-- (a deck may set `pre_default` — the tape's is 0, REPLACE). A deck with a
-- `freeze` key (the tape) holds instead: capture stops and the loop
-- regenerates at full pre; decks without one read the default 0 and the
-- branch is inert.
function M.update_rec(d)
  local frozen = get(d, "freeze", 0) == 1
  -- STOP gates capture too (the head is frozen anyway; an armed deck resumes
  -- recording on START, like the engine's record head)
  local on = get(d, "rec", 0) == 1 and not frozen
    and pget("stop_all", 0) == 0
  -- softcut's REC FLAG STAYS ON. A voice moves its write index only while the
  -- flag is on, so a head that played with it off writes at its last set
  -- position, not where it reads: the first pass on a fresh deck landed outside
  -- its own loop and the deck played silence. Heard on the device, 2026-11-06.
  -- These two levels are the gate: rec 0 and pre 1 write nothing, bit for bit.
  local rec = on and 1 or 0
  local pre = on and get(d, "pre", d.pre_default or 1) or 1
  -- A punch ramps over 5ms, so it does not print a step into the audio. The ramp
  -- never lands exactly, and an idle deck must not drift, so the next phase
  -- event (settle_rec) turns it off and lands the levels.
  local ramp = d.rec_on ~= nil and d.rec_on ~= on
  d.rec_on = on
  d.rec_lv, d.pre_lv = rec, pre
  d.rec_settling = ramp
  both(d, function(v)
    sc.recpre_slew_time(v, ramp and 0.005 or 0)
    sc.rec(v, 1)
    sc.rec_level(v, rec)
    sc.pre_level(v, pre)
  end)
end

function M.settle_rec(d)
  if not d.rec_settling then return end
  d.rec_settling = false
  both(d, function(v)
    sc.recpre_slew_time(v, 0)
    sc.rec_level(v, d.rec_lv)
    sc.pre_level(v, d.pre_lv)
  end)
end

-- loop bounds, in seconds, inside this deck's own region
function M.update_loop(d)
  local a = d.from + clamp(get(d, "start", 0), 0, 1) * d.len
  local b = d.from + clamp(get(d, "end", 1), 0, 1) * d.len
  local lo, hi = math.min(a, b), math.max(a, b)
  -- softcut's 0.1s minimum, held INSIDE the region: floored past the end, a
  -- loop parked at the far right would read (and record) the first 100ms of
  -- the NEXT deck's region
  if hi - lo < 0.1 then
    hi = math.min(lo + 0.1, d.from + d.len)
    lo = hi - 0.1
  end
  both(d, function(v)
    sc.loop_start(v, lo)
    sc.loop_end(v, hi)
  end)
  M.update_fade(d)      -- the seam is capped against the loop; the loop moved
end

-- The JOIN, where the loop ends and starts again. Softcut fades between the
-- two over this long. Short is a clean cut and a hard downbeat, which is what
-- a drum loop wants. Long is a blend that hides the join landing in the
-- middle of a held note, which is what a pad wants. One fixed value cannot
-- suit both, and this is the number that decides whether a loop sounds tight
-- or smeared.
function M.update_fade(d)
  -- ...but never longer than the loop can absorb. The knob goes to half a
  -- second and a loop can be as short as a tenth of one, so a scene recall
  -- can leave the fade longer than the loop it has to cross. The deck then
  -- spends all its time fading and goes quiet, while the page still draws it
  -- bright. A quarter of the loop is as long as it can usefully get.
  local f = math.min(get(d, "fade", 0.02), M.loop_secs(d) * 0.25)
  both(d, function(v) sc.fade_time(v, f) end)
end

-- stereo WIDTH. 1 is the deck's own hard L/R, 0 collapses it to the centre.
-- Two decks stacked on related material, both full-width, are a wall; pulling
-- one of them in is what leaves room to hear the other around it.
function M.update_width(d)
  local w = clamp(get(d, "width", 1), 0, 1)
  sc.pan(d.va, -w)
  sc.pan(d.vb, w)
end

-- drop both heads at a normalized position inside this deck's region.
-- softcut reports the head every 25 ms, and a report from the place the head
-- left can still be on its way: M.trust drops those.
function M.jump(d, ph)
  ph = clamp(ph, 0, 1)
  local at = d.from + ph * d.len
  both(d, function(v) sc.position(v, at) end)
  d.jump_at, d.jump_left = ph, 3
end

-- Is this report of the head (`ph`, 0..1 in the region) to be believed? `was`
-- is the place the last believed one gave. After a jump, up to three reports
-- that are not near the place the head went to are dropped: without this a
-- pass that closed 30 ms after it opened took the old place as its end. A
-- believed report that lies far before the last one is a head that came
-- round the region's end (d.wrapped). A pass reads that when it closes: its
-- loop cannot cross the end.
function M.trust(d, ph, was)
  if (d.jump_left or 0) > 0 then
    if math.abs(ph - d.jump_at) > 0.02 then
      d.jump_left = d.jump_left - 1
      return false
    end
    d.jump_left = 0
  end
  if ph < was - 0.5 then d.wrapped = true end
  return true
end

-- does this deck play forward? A stopped deck does not.
function M.forward(d)
  return get(d, "rate", 1) * (get(d, "reverse", 0) == 1 and -1 or 1) > 0
end

-- how long this deck's loop actually is, in seconds. One law for every
-- reader, so they cannot disagree.
function M.loop_secs(d)
  local a = clamp(get(d, "start", 0), 0, 1)
  local b = clamp(get(d, "end", 1), 0, 1)
  return math.max(math.abs(b - a) * d.len, 0.1)
end

function M.update_all(d)
  M.update_rate(d)
  M.update_rec(d)
  M.update_loop(d)      -- (sends the seam too: update_loop ends in update_fade)
  M.update_level(d)
  M.update_width(d)
end

-- ---------------------------------------------------------------------------
-- the loop-pedal law
-- ---------------------------------------------------------------------------
-- A deck with NO material takes its loop length from the pass you record:
-- arming opens the loop to the whole region so nothing you play is cut off,
-- and marks where the head is. Disarming closes the loop around exactly what
-- you played and drops the head back at its start, so it plays back tight
-- immediately. Without this a fresh deck loops the WHOLE 60-second region,
-- which is a deck, not a looper.
--
-- A deck that ALREADY holds audio keeps its loop and overdubs into it. That
-- is the entire difference between defining a loop and adding to one, and it
-- is why a deck defaults to overdub while the tape defaults to replace.
--
-- How accurately it can catch the moment you pressed the key is limited by
-- how often softcut reports the playhead position, which is every 25 ms. That
-- is close, but never exact.
-- THE way to move a start/end pair (a loop, the take window). Each edge is a
-- separate write, so in between the new start sits against the OLD end; if
-- that crosses the pair, every reader sorts it into a region that is neither
-- the old one nor the new one, and the deck's 100ms floor can jump the head.
-- So the WIDENING edge goes first: moving left, the start; moving right, the
-- end. With an ordered pair the halfway state is then always ordered, and on a
-- slide right it still contains the old region, so the head is not stranded
-- outside the loop. The take window, the grid spans, the encoder slides and
-- motion replay all write through here.
function M.set_pair(sid, eid, lo, hi)
  if lo < pget(sid, 0) then
    params:set(sid, lo); params:set(eid, hi)
  else
    params:set(eid, hi); params:set(sid, lo)
  end
end

local function set_bounds(d, lo, hi) M.set_pair(p(d, "start"), p(d, "end"), lo, hi) end
M.set_loop = set_bounds

function M.arm_loop(d)
  d.arm_phase, d.arm_was = nil, nil
  d.gen = d.gen + 1                   -- a live pass outranks a load in flight
  if d.any then return end            -- overdub into the established loop
  -- Remember the loop we are about to widen. If the recording turns out to be
  -- too short to be a loop, close_loop puts this back. Widening is only
  -- preparation, and preparation that comes to nothing must not cost the
  -- player the loop they had set. Tapping REC by mistake takes a single
  -- frame, and without this it left the deck looping the whole 60 seconds.
  d.arm_was = { clamp(get(d, "start", 0), 0, 1), clamp(get(d, "end", 1), 0, 1) }
  set_bounds(d, 0, 1)
  -- A NEW LOOP STARTS AT THE START OF THE REGION (the forty-eighth change).
  -- The head runs on while nothing records, so a pass began anywhere in the
  -- region, and one that crossed its end could not become a loop: the whole
  -- region stayed open, and the pass came back once a minute. A deck that
  -- plays backward keeps the old law: its pass starts where the head is.
  -- The tape's own copy of this law is in four.lua (tape_rec).
  d.arm_jumped = M.forward(d)
  if d.arm_jumped then
    M.jump(d, 0)
    d.phase = 0
  end
  d.wrapped = false
  d.arm_phase = d.phase
end

-- forget the mark without closing anything: the erase disarms on its way to
-- wiping the deck, and closing a loop around material about to be destroyed
-- is noise. The loop stays as the arm left it, because the erase resets it.
function M.abort_loop(d) d.arm_phase, d.arm_was, d.arm_jumped = nil, nil, nil end

function M.close_loop(d)
  local a, was, jumped = d.arm_phase, d.arm_was, d.arm_jumped
  d.arm_phase, d.arm_was, d.arm_jumped = nil, nil, nil
  if not a then return end
  local b = d.phase
  -- Which way the head was moving decides which end of the recording is the
  -- loop START. Playing backwards, the head counts DOWN, so the recording
  -- runs from where it stopped to where it started. Assuming it always counts
  -- up left a reversed deck with either no loop at all, or a loop around the
  -- one stretch it had just skipped over.
  local back = get(d, "rate", 1) * (get(d, "reverse", 0) == 1 and -1 or 1) < 0
  local lo, hi = a, b
  if back then lo, hi = b, a end
  -- A forward pass that came round the region's end is longer than the
  -- region. It filled it: the loop is the whole region, as the arm left it.
  if jumped and d.wrapped then return end
  -- The head ran off the end and round to the start, or barely moved at all.
  -- A loop cannot span that join, so there is nothing to close here. Put back
  -- the loop we widened, rather than leave the deck on the full 60 seconds,
  -- which is the once-a-minute playback this whole law exists to prevent.
  if (hi - lo) < (0.1 / d.len) then
    if was then
      set_bounds(d, was[1], was[2])
      -- the arm moved the head to the region's start: put it back on the loop
      if jumped then M.jump(d, was[1]) end
    end
    return
  end
  set_bounds(d, lo, hi)
  M.jump(d, clamp(get(d, "start", 0), 0, 1))
end

-- The zeros of a deck's region. sc.buffer_clear() takes the whole buffer with
-- it, so a deck that shares the buffer clears its region. A deck that is ALONE
-- in softcut (the tape, since the layer decks left) clears it whole: on the
-- norns a region clear makes the scsynth miss blocks (1 or 2 xruns each time
-- over four PV tracks, from 10 s of region up), and the whole clear makes none.
function M.zero(d)
  if d.alone then sc.buffer_clear() else sc.buffer_clear_region(d.from, d.len) end
end

-- wipe THIS deck only
function M.clear(d)
  d.gen = d.gen + 1
  M.zero(d)
  -- through mpages when it is there, so a repaint still queued for this strip
  -- (a PSET restore fills strips one after another) is cancelled with it and
  -- cannot draw the old waveform over the silence
  if C.clear_bins then C.clear_bins(d.wave)
  else for i = 1, #d.wave do d.wave[i] = 0 end end
  d.wave_bin = 0
  d.any = false
  d.mat_lo, d.mat_hi = nil, nil
end

function M.start(d)
  sc.enable(d.va, 1); sc.enable(d.vb, 1)
  -- voice -> buffer channel, and the stereo split
  sc.buffer(d.va, 1); sc.buffer(d.vb, 2)
  both(d, function(v)
    sc.play(v, 1)
    sc.loop(v, 1)
    sc.position(v, d.from)
    sc.level_slew_time(v, 0.05)
    sc.rate_slew_time(v, 0.05)
    -- softcut's filter sections default in a way that can mute a voice; force
    -- them open, the same as init_tape does
    sc.pre_filter_dry(v, 1.0)
    sc.pre_filter_lp(v, 0.0)
    sc.post_filter_dry(v, 1.0)
    sc.post_filter_lp(v, 0.0)
  end)
  -- each voice takes one input channel: lower = L, upper = R
  for ch = 1, 2 do
    sc.level_input_cut(ch, d.va, ch == 1 and 1.0 or 0.0)
    sc.level_input_cut(ch, d.vb, ch == 2 and 1.0 or 0.0)
  end
  sc.buffer_clear_region(d.from, d.len)
  M.update_all(d)
  -- the playhead poll drives this deck's needle and its waveform painting
  sc.phase_quant(d.va, 0.025)
end

-- ---------------------------------------------------------------------------
-- where the material is
-- ---------------------------------------------------------------------------
-- The stretch of the region a deck has written, 0..1. A scene recall clamps a
-- stored loop to it, so a scene captured before the deck was recorded cannot
-- reopen the loop over 60 seconds of nothing (mscenes' clamp_stored). Grown
-- from the softcut phase events while the deck records; a load or a PSET
-- restore sets it, a clear forgets it. The tape keeps one too (lib/mtape.lua).
function M.track_extent(d, ph)
  if d.mat_hi then
    if ph < d.mat_lo then d.mat_lo = ph end
    if ph > d.mat_hi then d.mat_hi = ph end
  else
    d.mat_lo, d.mat_hi = ph, ph
  end
end

-- the extent as the clamp should use it, or nil when nothing is known. Widened
-- by 50ms each side: the phase events that grow it come every 25ms, so the
-- last one before a pass ends can be that far behind the head.
function M.extent(d)
  if not (d.mat_lo and d.mat_hi) then return nil end
  local pad = 0.05 / d.len
  return clamp(d.mat_lo - pad, 0, 1), clamp(d.mat_hi + pad, 0, 1)
end

-- how much of the region a PSET save writes: up to the end of the material
-- (plus the 50ms the extent can lag), or the whole region when the extent is
-- not known. A 2s loop no longer saves 60 seconds of mostly silence, and a
-- smaller file is less exposed to a save-then-quit cutting the write short.
function M.save_secs(d)
  if not d.mat_hi then return d.len end
  return math.min(d.len, d.mat_hi * d.len + 0.05)
end

-- after a PSET wav is read back into the region: the material is what the
-- file held, from the region's start (the save began there)
function M.restored_extent(d, path)
  local dur
  if C.wav_info then dur = select(2, C.wav_info(path)) end
  d.mat_lo, d.mat_hi = 0, dur and clamp(dur / d.len, 0, 1) or 1
end

-- ---------------------------------------------------------------------------
-- the phase poll
-- ---------------------------------------------------------------------------
-- mtape owns the single sc.event_phase handler and handles the tape's voice
-- itself. A deck built with M.new needs its events handed to this. Position
-- drives the page; while recording
-- it also paints the picture, because softcut exposes no per-voice output
-- meter — the amplitude has to come from what is being fed in.
function M.on_phase(voice, pos)
  for i = 1, #M.decks do
    local d = M.decks[i]
    if d.va == voice then
      local ph = clamp((pos - d.from) / d.len, 0, 1)
      if not M.trust(d, ph, d.phase) then return end   -- a report from before a jump
      d.phase = ph
      M.settle_rec(d)
      if get(d, "rec", 0) == 1 then
        M.track_extent(d, d.phase)
        local a = C.cut_rec_amp()   -- what softcut records: the shared law
        if a > 0.01 then d.any = true end
        d.wave_bin = C.paint_bins(d.wave, d.wave_bin,
          math.floor(d.phase * (#d.wave - 0.001)) + 1, a, get(d, "pre", 1))
      end
      return
    end
  end
end

-- ---------------------------------------------------------------------------
-- lifecycle
-- ---------------------------------------------------------------------------

function M.init(ctx)
  C = ctx
  pget, clamp = ctx.pget, ctx.clamp
end

return M

end)()
local Minput = (function()  -- inlined lib/minput.lua
-- minput: chromatic note input — midi notes and the usb typing keyboard.
--
-- every note goes through ctx.route_note, which sends it one of two ways:
--   pad input OFF  the note retunes the drone: `pitch` = 2^(semitones/12)
--                  relative to root_note (middle C with the default root plays
--                  the sample as recorded; the 0.25-4 spec covers ±24 st).
--                  last-note priority, so the release is ignored.
--   pad input ON   the note gates a polyphonic PADS voice (note mod 8), held
--                  until its release.
-- CC mappings (PMAP) are handled by the system and unaffected by this.

local midi_devices = {}

local C     -- shared ctx, bound at init
local pget, ptoggle, FPS

-- true when vport i holds the device the grid layer adopted (midigrid, OR the
-- native Launchpad Mini MK3 colour driver): its note-ons are grid pads, not
-- notes. norns dispatches midi to BOTH the device-level handler (which those
-- use) and the vport-level handler (which we use), so without this filter every
-- pad press would also yank `pitch` to whatever the pad's raw note maps to.
local function is_grid_vport(i)
  local G = C.grid
  local gg = G.gg
  local vp = midi.vports[i]
  local dev = vp and vp.device
  if not dev then return false end
  -- an Exquis whose pads are the surface (PADS): its notes are pads. In KEYS
  -- its notes are notes, and they pass.
  local ex = G.ex
  if ex and ex.surface and (dev == ex.device or dev.name == ex.device.name) then
    return true
  end
  if not ((G.midigrid_loaded or G.have_launchpad) and gg and gg.device) then return false end
  return dev == gg.device or dev.name == gg.device.name
end

-- THE FADER BLOCK (the sixtieth change): eight faders of a MIDI controller
-- in a row, on `fader_ch`, from CC `fader_cc` up, are the mixer: the four
-- track levels, the delay's and the reverb's WET, eng <> tape and the master.
-- PICKUP: a fader takes its knob over only when it reaches or passes the
-- knob's value, so a scene, a hand or a PSET that moved the knob is never
-- yanked back by a fader left elsewhere. A knob moved by anything else lets
-- go of its fader again.
local FADERS = 8
local fader_ids = {}           -- the eight param ids, built at the first CC
local caught, last_raw, prev_x = {}, {}, {}
local FADER_EXTRA = { "delay_mix", "rev_mix", "mix", "out_level" }

-- a CC on the fader block: true when it was one of ours
-- a new channel or first CC is another controller: every fader picks up again
local function fader_reset()
  for k = 1, FADERS do caught[k], last_raw[k], prev_x[k] = nil, nil, nil end
end

local function fader_cc(msg)
  local ch = pget("fader_ch", 0)
  if ch < 1 or msg.ch ~= ch then return false end
  local k = (msg.cc or -1) - math.floor(pget("fader_cc", 0) + 0.5) + 1
  if k < 1 or k > FADERS then return false end
  if not fader_ids[1] then
    for n = 1, 4 do fader_ids[n] = C.LEVEL_ID[n] end
    for j = 1, 4 do fader_ids[4 + j] = FADER_EXTRA[j] end
  end
  local id = fader_ids[k]
  local cs = id and params.lookup[id] and params:lookup_param(id).controlspec
  if not cs then return true end
  local x = (msg.val or 0) / 127
  local cur = cs:unmap(params:get(id))
  if caught[k] and last_raw[k] and math.abs(cur - last_raw[k]) > 0.002 then
    caught[k] = false            -- something else moved the knob
  end
  if not caught[k] then
    local px = prev_x[k]
    if math.abs(x - cur) <= 1.5 / 127 or (px and (px - cur) * (x - cur) <= 0) then
      caught[k] = true
    end
  end
  prev_x[k] = x
  if caught[k] then
    params:set(id, cs:map(x))
    last_raw[k] = cs:unmap(params:get(id))
    C.flash_id, C.flash_until = id, C.frame + FPS
  end
  return true
end

local function midi_event(data, vport)
  if is_grid_vport(vport) then return end
  local msg = midi.to_msg(data)
  -- the picture hears every port (an Octatrack on the TRS input, for one)
  if C.osc and C.osc.midi_in then C.osc.midi_in(msg, vport) end
  -- a mapped CC is a hand on the instrument too (idle dim); notes count
  -- through route_note. clock and other system messages do not.
  if msg.type == "cc" then
    C.touch_input()
    if fader_cc(msg) then return end
  end
  -- pressure is a modulation source (the PRESS shape, lib/mlfo.lua): channel
  -- pressure for an MPE keyboard, which plays one note a channel, and key
  -- pressure for the others. Never gated: it moves nothing until a modulator
  -- listens, and a gated zero would leave a knob held open.
  if msg.type == "channel_pressure" then
    C.lfo.press_in((msg.ch or 1) * 256 + 128, (msg.val or 0) / 127)
    return
  elseif msg.type == "key_pressure" then
    C.lfo.press_in((msg.ch or 1) * 256 + (msg.note or 0), (msg.val or 0) / 127)
    return
  end
  -- both edges: note-on gates a voice / retunes the drone, note-off releases
  -- a voice (the drone is last-note, so it ignores the release)
  local z, note
  if msg.type == "note_on" and (msg.vel or 0) > 0 then
    z, note = 1, msg.note
  elseif msg.type == "note_off" or (msg.type == "note_on" and (msg.vel or 0) == 0) then
    z, note = 0, msg.note
  else
    return
  end
  -- a key that came up presses no more, whatever its last pressure message said
  if z == 0 then
    C.lfo.press_in((msg.ch or 1) * 256 + 128, 0)
    C.lfo.press_in((msg.ch or 1) * 256 + note, 0)
  end
  -- the gates apply to PRESSES only: a release belongs to the press that
  -- opened it, so keys_enable going off (or the channel changing) mid-hold
  -- must never swallow a note-off and strand a pad voice — the same trap the
  -- typing keyboard guards below. a release for a note we never opened is a
  -- no-op inside route_note/pad_trigger.
  if z == 1 then
    if pget("keys_enable", 1) == 0 then return end
    local ch = pget("midi_channel", 0)
    if ch > 0 and msg.ch ~= ch then return end
  end
  -- route_note decides drone vs pad from `pad_input`; id offset by 1000 so
  -- MIDI voice ids never collide with grid/screen pad ids
  C.route_note(1000 + note, 2 ^ ((note - pget("root_note", 60)) / 12), note, z, note)
end

-- USB typing keyboard: ableton-style musical typing. the A-row is the white
-- keys, the W-row the black keys — A plays the sample as recorded, and Z/X
-- shift the octave (kb_octave). semitone offsets are root-relative, so the
-- root_note param only concerns MIDI (which sends absolute note numbers).
local KB_NOTES = {
  A = 0, W = 1, S = 2, E = 3, D = 4, F = 5, T = 6, G = 7, Y = 8,
  H = 9, U = 10, J = 11, K = 12, O = 13, L = 14, P = 15,
  SEMICOLON = 16, APOSTROPHE = 17,
}

-- key code -> the semitone it was pressed AT, while held. the id a voice is
-- opened with must be keyed on the physical KEY, not the note, or an octave
-- shift mid-hold would compute a different id at release and strand the voice
-- (the grid keys on the pad coordinate for the same reason).
local kb_held = {}

local M = {}
M.fader_cc, M.fader_ids, M.caught = fader_cc, fader_ids, caught
M.fader_reset = fader_reset

function M.init(ctx)
  C = ctx
  pget, ptoggle, FPS = ctx.pget, ctx.ptoggle, ctx.FPS
  keyboard.code = function(code, value)
    if value == 2 then return end           -- autorepeat: a held key is not a new press
    -- a release belongs to the press that opened it: if this key started a
    -- voice, close it whatever the gates say NOW. the menu opening or
    -- keys_enable going off mid-hold must never leave a note sounding.
    if value == 0 then
      local st = kb_held[code]
      if st then
        kb_held[code] = nil
        local semi = st + 12 * pget("kb_octave", 0)
        C.route_note(3000 + st, 2 ^ (semi / 12), semi, 0)
      end
      return
    end
    if norns.menu.status() then return end  -- the menu owns typing (PSET names)
    -- SPACE = master stop/start, ableton muscle memory. it's transport, not
    -- note input, so it works even with keys_enable off
    if code == "SPACE" then
      C.touch_input()
      ptoggle("stop_all")
      return
    end
    if pget("keys_enable", 1) == 0 then return end
    if code == "Z" or code == "X" then
      C.touch_input()
      params:delta("kb_octave", code == "X" and 1 or -1)
    else
      local st = KB_NOTES[code]
      if st then
        local semi = st + 12 * pget("kb_octave", 0)
        -- both edges, like the grid: route_note plays pad (semi mod 8) as a
        -- polyphonic voice in pad mode, or retunes the mono drone (which
        -- ignores the release) otherwise. ids 3000+ keep typing-keyboard
        -- voices clear of MIDI (1000+), grid (2000+ note / 2600+ slice), the
        -- screen bank (0..8) and the sequencer (4000).
        kb_held[code] = st
        C.route_note(3000 + st, 2 ^ (semi / 12), semi, 1)
        -- in pad mode `pitch` doesn't move, so don't swell a value that isn't
        -- changing — the pad cell lighting is the feedback there
        if pget("pad_input", 0) == 0 then
          C.flash_id, C.flash_until = "pitch", C.frame + FPS
        end
      end
    end
  end
end

function M.init_midi()
  -- connect every vport: any keyboard works, including ones plugged in later
  for i = 1, #midi.vports do
    midi_devices[i] = midi.connect(i)
    midi_devices[i].event = function(data) midi_event(data, i) end
  end
end

function M.cleanup()
  for _, d in ipairs(midi_devices) do d.event = nil end
  keyboard.code = nil
  C.lfo.press_clear()
  kb_held = {}   -- the voices themselves are released by ctx.pads_all_off()
end

return M

end)()
local Mgrid = (function()  -- inlined lib/mgrid.lua
-- mgrid: the optional 8x8 grid surface — monome grid, or launchpad-style
-- controllers via midigrid.
--
-- native monome grids just work; with the midigrid library installed
-- (~/dust/code/midigrid) a launchpad-family or APC mini controller stands
-- in — but only when no real grid is attached (a monome on grid vport 1
-- wins). every pad drives params, the same single source of truth as keys,
-- encoders, and MIDI CCs.
--
-- THE SPINE: rows 1-2 and 7-8 NEVER change
-- meaning; only the workspace rows 3-6 follow the screen page. your hands
-- always know where the scenes, the transport, and the notes are.
--
--   row 1  SCENES, from any page: tap = recall · hold = PEEK (borrow the
--          scene, release comes home — the punch law) · with the SCENE
--          workspace's CAP/CLR modifiers held: capture / clear
--   row 2  STATE STRIP: [rec][tape rec][tape rev, hold][pv frz][tape frz]
--          [notes->pads] · [DRY] [STOP]
--   rows 3-6  the WORKSPACE (follows the page):
--     main   row 3 window slices (span gesture; write head glows while
--            recording) · row 4 tape loop slices (same gesture) · row 5
--            mode radio x1-6 (OFF GRAIN WARP PV PLAY CLOUD) + pitch reset x7 /
--            pitch quantize x8 · row 6 the beat repeat, held: x1-5 = 1/2 to
--            1/32 (slide a finger across them for a roll) · x6/x7 visuals look
--            back/next · x8 visuals FLASH, held
--     PADS   row 3 the 8 slice pads (finger-drum, held) · row 5 slice select ·
--            row 6 voice type x1 · sequencer run x3, fewer/more hits x5/x6 ·
--            notes->pads x8
--     SCENE  row 3 AIM (point the morph without jumping) · row 5 the morph
--            bar · row 6 [CAP mod][CLR mod] · [CHAOS, hold] · · [◄ back]
--   rows 7-8  ONE piano octave (black row above white; same shape as the
--          typing keyboard). row 7 gap pads x1/x8 = octave -/+. lit: the
--          drone's pitch, or in pad mode the keys whose pad is sounding
--
-- On a Launchpad Mini MK3 the arrows step the page (left/right, like E1) and
-- the scene selector (up/down), and the pad is picked up on hot-plug.
--
-- An Exquis works beside any of these, or alone: its pads show rows 1 to 6
-- folded onto the hexagons, or play as its own keyboard. See the Exquis
-- section below for the layout.

local floor, min, max, log = math.floor, math.min, math.max, math.log
-- the visuals look names (lib/mosc.lua owns the list; kept in step by test_control)
local Mosc_LOOKS = { "AUTO", "BARS", "FILTER", "SHAPES", "RINGS", "MOSAIC", "TUNNEL", "WAVES", "FACETS" }

local M = { gg = nil, have_launchpad = false, midigrid_loaded = false,
            reconnect_due = false,
            ex = nil, ex_due = false }   -- an Exquis, beside the grid (see below)

local grid_mod = grid
local no_monome = false    -- true when no native monome grid holds grid vport 1
do
  local gname = (grid.vports and grid.vports[1] and grid.vports[1].name)
    or "none"
  no_monome = gname == "none"
  -- midigrid is loaded as the FALLBACK backend; a Launchpad Mini MK3 is
  -- preferred over it at connect time (real per-pad colour vs midigrid's
  -- monochrome emulation).
  if no_monome and util.file_exists(_path.code .. "midigrid") then
