  "scene_recall",
  "scene_next", "scene_clear", "scene_safe_capture", "scene_safe_restore",
  "chaos_throw", "orbit_on", "orbit_rate", "orbit_reach",
  -- the sequencer: a second machine on the clock. A loop replaying its knobs
