  TARGETS = TARGETS, SHAPES = SHAPES, PERIOD_NAMES = PERIOD_NAMES, N = N,
  env = 0,        -- the input envelope, 0..1, shared by every ENV modulator
  press = 0,      -- the keyboard pressure, 0..1, shared by every PRESS modulator
