  if s == 2 then return pget("scene_morph_amt", 0) end
  local lfo = C.lfo
  if not lfo then return nil end
  if s == 3 then return lfo.env end
  if s == 4 or s == 5 then return lfo.mods[s - 3].out end
  return nil
end

