add("look", "vis_look")
add("flash", "vis_flash")
add("mode", "mode")
add("rec", "rec")
add("freeze", "freeze")
add("env", function() return C.lfo and C.lfo.env or 0 end)
add("lfo1", function() return C.lfo and C.lfo.mods[1].out or 0 end)
add("lfo2", function() return C.lfo and C.lfo.mods[2].out or 0 end)
