-- window and knobs, so the visuals can give it a layer of its own
add("t2_on", function()
  return (pget("t2_mode", 1) ~= 1 and pget("t2_level", 1) > 0.001
    and C.track_gain(2) > 0) and 1 or 0
end)
add("t2_mode", "t2_mode")
add("t2_level", "t2_level")
