add("t2_win_start", "t2_pos_start")
add("t2_win_end", "t2_pos_end")
add("t2_size", "t2_size", true)
add("t2_density", "t2_density", true)
add("t2_pitch", "t2_pitch", true)
add("t2_cutoff", "t2_cutoff", true)
