-- the modes and switches as they are.
add("focus", "track_sel")
add("t3_mode", "t3_mode")
add("t4_mode", "t4_mode")
add("lvl1", "grain_level", true)
add("lvl2", "t2_level", true)
add("lvl3", "t3_level", true)
add("lvl4", "t4_level", true)
add("dly1", "fx_dly", true)
add("dly2", "t2_fx_dly", true)
add("dly3", "t3_fx_dly", true)
add("dly4", "t4_fx_dly", true)
add("rev1", "fx_rev", true)
add("rev2", "t2_fx_rev", true)
add("rev3", "t3_fx_rev", true)
add("rev4", "t4_fx_rev", true)
add("mix", "mix", true)
add("out_level", "out_level", true)
add("stop", "stop_all")
add("mrec", "motion_rec")
add("mplay", "motion_play")
add("mbars", "motion_bars")
add("src", "rec_source")
add("scene_a", "scene_slot_a")
add("cpu", function() return C.cpu_high and 1 or 0 end)
-- the filled scene slots, one bit each (slot 1 is 1, slot 8 is 128)
add("filled", function()
  local s, b = C.scene and C.scene.slots, 0
  if s then for i = 1, 8 do if s[i] then b = b + (1 << (i - 1)) end end end
  return b
end)

local M = { FIELDS = FIELDS, on = false, host = nil, port = nil, errors = 0 }

-- A host given as a name (the computer's name.local) is resolved here, once a
-- minute, and the number is what osc.send gets. osc.send looks a name up on
-- every message, which would be 100 lookups a second on the frame clock. A
-- name that cannot be resolved keeps the last number. A computer whose
-- address changed overnight is found again within a minute.
local RESOLVE_EVERY = 60   -- seconds
local resolved, resolved_name, resolved_at = nil, nil, -1e9

local function is_number_host(h)
  return h:match("^%d+%.%d+%.%d+%.%d+$") ~= nil
end

local function resolve(h)
  if is_number_host(h) then return h end
  local now = C.frame / C.FPS
  if resolved_name == h and now - resolved_at < RESOLVE_EVERY then return resolved end
  resolved_name, resolved_at = h, now
  local ok, p = pcall(io.popen, "getent ahostsv4 '" .. h:gsub("[^%w%.%-_]", "") .. "' 2>/dev/null")
  if ok and p then
    local line = p:read("l")
    p:close()
    local ip = line and line:match("^(%d+%.%d+%.%d+%.%d+)")
    if ip then
      if ip ~= resolved then print("four: osc host " .. h .. " is " .. ip) end
      resolved = ip
    end
  end
  return resolved
end
M.resolve = resolve

local dest = { "", 0 }     -- handed to osc.send; rebuilt in place on a change
-- (declared here, above M.tick, which resets it: below, tick wrote a global
-- and the cap of ev_send never opened again after 24 events)
local sent_ev = 0
local one = { 0 }          -- the argument list, reused for every message

local function value(f)
  local v
  if f.id then
    v = pget(f.id, 0)
    if f.norm then
      local p = params:lookup_param(f.id)
      local cs = p and p.controlspec
      if cs and cs.unmap then v = cs:unmap(v) end
    end
  else
    v = f.read()
  end
  if type(v) == "number" and v ~= floor(v) then v = floor(v * 1000 + 0.5) / 1000 end
  return v
end

function M.tick()
  if pget("osc_on", 0) ~= 1 or not (osc and osc.send) then
    M.on = false
    return
  end
  local name = params:get("osc_host")
  local port = floor(pget("osc_port", 9000) + 0.5)
  local host = name ~= nil and name ~= "" and resolve(name) or nil
  if host == nil then M.on = false; return end
  local full = not M.on or host ~= M.host or port ~= M.port
    or C.frame % (REFRESH * C.FPS) == 0
  if host ~= M.host or port ~= M.port then
    M.host, M.port = host, port
    dest[1], dest[2] = host, port
  end
  M.on = true
  sent_ev = 0
  for i = 1, #FIELDS do
    local f = FIELDS[i]
    local v = value(f)
    if full or v ~= f.last then
      f.last = v
      one[1] = v
      if not pcall(osc.send, dest, f.path, one) then
        M.errors = M.errors + 1
        if M.errors == 1 then print("four: osc send failed to " .. host .. ":" .. port) end
      end
    end
  end
end

-- CONTROL FROM THE COMPUTER (the sixtieth change). visuals/bridge.js sends
-- what the control page moves to the norns's OSC port (10111):
--   /four/set   <id> <value>    the param's own value (a mode, a switch)
--   /four/norm  <id> <0..1>     a position on the knob (a fader)
--   /four/press <id>            a momentary param: a press and a release
-- Only the ids below can be moved through /four/: the mixer, the modes, the
-- transports (REC and UNDO write the take, as on the device) and the scenes,
-- and never a file or the link's own settings. This is a filter for /four/,
-- not a wall: the norns itself also takes /param/<id> from any host on the
-- network. A move is a hand on the instrument: the motion looper records it,
-- as it records a MIDI knob.
local ALLOW = {}
for _, id in ipairs({ "mode", "t2_mode", "t3_mode", "t4_mode", "track_sel",
    "grain_level", "t2_level", "t3_level", "t4_level",
    "mute_1", "mute_2", "mute_3", "mute_4",
    "fx_dly", "t2_fx_dly", "t3_fx_dly", "t4_fx_dly",
    "fx_rev", "t2_fx_rev", "t3_fx_rev", "t4_fx_rev",
    "delay_mix", "rev_mix", "mix", "out_level", "dry_wet", "cutoff", "resonance",
    "stop_all", "rec", "rec_source", "motion_rec", "motion_play", "motion_bars",
    "scene_slot", "scene_slot_a", "scene_morph_amt", "freeze", "vis_look" }) do
  ALLOW[id] = "set"
end
for _, id in ipairs({ "scene_recall", "scene_capture", "scene_next",
    "scene_safe_restore", "take_undo", "vis_flash" }) do
  ALLOW[id] = "press"
end
M.ALLOW = ALLOW

function M.osc_in(path, args)
  local id = args and args[1]
  if type(id) ~= "string" or not ALLOW[id] or not params.lookup[id] then return false end
  if path == "/four/set" and ALLOW[id] == "set" and type(args[2]) == "number" then
    -- the value as the param's own type would hold it: the norns does not
    -- round an option, a number or a binary, and a 2.5 there breaks a page
    local p = params:lookup_param(id)
    local v = args[2]
    if v ~= v then return false end                       -- NaN
    if p.count then
      v = math.min(math.max(math.floor(v + 0.5), 1), p.count)
    elseif p.controlspec then
      local cs = p.controlspec
      v = math.min(math.max(v, math.min(cs.minval, cs.maxval)), math.max(cs.minval, cs.maxval))
    elseif p.min and p.max then
      v = math.min(math.max(math.floor(v + 0.5), p.min), p.max)
    else
      v = v >= 0.5 and 1 or 0                              -- a binary
    end
    params:set(id, v)
  elseif path == "/four/norm" and ALLOW[id] == "set" and type(args[2]) == "number" then
    local cs = params:lookup_param(id).controlspec
    if not cs then return false end
    params:set(id, cs:map(math.min(math.max(args[2], 0), 1)))
  elseif path == "/four/press" and ALLOW[id] == "press" then
    params:set(id, 1)
    params:set(id, 0)
  else
    return false
  end
  if C.touch_input then C.touch_input() end
  return true
end

function M.init(ctx)
  C = ctx
  pget = ctx.pget
  -- the norns hands a script every OSC message it does not handle itself
  -- (its own /param/ path included); osc.cleanup takes this away again
  if osc then
    osc.event = function(path, args, from)
      if type(path) == "string" and path:sub(1, 6) == "/four/" then M.osc_in(path, args) end
    end
  end
end

-- MIDI events for the picture (an Octatrack on the TRS MIDI input, or any
-- other MIDI source). lib/minput.lua hands every message of every port here.
-- A note, a CC, a program change and the transport go out at once as
-- /four/ev/<name> with integer arguments, so a hit lands on the beat
-- instead of waiting for the next frame. A CC that did not change is not
-- sent again. At most EVENT_CAP events leave per frame, so a knob sweep or a
-- busy pattern cannot flood the Wi-Fi. Clock messages are never forwarded.
local EVENT_CAP = 24
local last_cc = {}
local evargs = { 0, 0, 0 }
local evrun = { 0 }

local function ev_send(name, args)
  if sent_ev >= EVENT_CAP then return end
  sent_ev = sent_ev + 1
  if not pcall(osc.send, dest, "/four/ev/" .. name, args) then
    M.errors = M.errors + 1
  end
end

function M.midi_in(msg, vport)
  if not (M.on and osc and osc.send) or pget("vis_midi", 1) ~= 1 then return end
  local t = msg.type
  if t == "note_on" and (msg.vel or 0) > 0 then
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.note or 0, msg.vel or 0
    ev_send("note", evargs)
  elseif t == "cc" then
    local key = (msg.ch or 1) * 128 + (msg.cc or 0)
    if last_cc[key] == msg.val then return end
    last_cc[key] = msg.val
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.cc or 0, msg.val or 0
    ev_send("cc", evargs)
  elseif t == "program_change" then
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.val or 0, 0
    ev_send("pc", evargs)
  elseif t == "start" or t == "continue" or t == "stop" then
    evrun[1] = t == "stop" and 0 or 1
    ev_send("run", evrun)
  end
end

-- the look the visuals show. Option 1 lets the visuals pick one by the page.
-- The order is mirrored by NAMES in visuals/hydra.js. It is a scene param
-- (lib/mscenes.lua), so a scene or a preset can bring its own look.
M.LOOKS = { "AUTO", "BARS", "FILTER", "SHAPES", "RINGS", "MOSAIC", "TUNNEL", "WAVES", "FACETS" }

-- The three connection params are remembered in a small file, so a norns that
-- is switched on tomorrow sends to the same computer with no setup. A pset
-- does not carry them: they are about this room, not about a sound.
local function cfg_path()
  return (_path and _path.data or "/home/we/dust/data/") .. "four/osc.cfg"
end

local loading, reading = false, false
local function cfg_save()
  if loading or reading then return end
  local f = io.open(cfg_path(), "w")
  if not f then return end
  f:write(string.format("%d\n%s\n%d\n", pget("osc_on", 0), params:get("osc_host") or "",
    floor(pget("osc_port", 9000) + 0.5)))
  f:close()
end

local function cfg_load()
  local f = io.open(cfg_path(), "r")
  if not f then return end
  local on, host, port = f:read("n"), nil, nil
  f:read("l"); host = f:read("l"); port = f:read("n")
  f:close()
  loading = true
  if host and host ~= "" then params:set("osc_host", host) end
  if port then params:set("osc_port", port) end
  if on then params:set("osc_on", on) end
  loading = false
end

M.cfg_reload = cfg_load   -- after a PSET read, which would put the old values back

function M.add_params()
  params:add_group("grp_osc", "visuals out (osc)", 6)
  params:add_option("vis_look", "visuals look", M.LOOKS, 1)
  params:add_binary("vis_flash", "visuals flash", "momentary", 0)   -- a hit on the picture, held
  params:add_binary("vis_midi", "midi to visuals", "toggle", 1)   -- notes, CCs, program changes, transport
  params:add_binary("osc_on", "osc out", "toggle", 0)
  params:add_text("osc_host", "osc host (ip or name.local)", "192.168.1.100")
  params:add_number("osc_port", "osc port", 1, 65535, 9000)
  for _, id in ipairs({ "osc_on", "osc_host", "osc_port" }) do params:set_action(id, cfg_save) end
  -- a PSET read puts its own values in these params (one saved after this
  -- change carries them): while it runs, nothing is written to the file, and
  -- the action_read hook restores the file's values afterwards
  local read = params.read
  if read then
    params.read = function(self, ...)
      reading = true
      local ok, err = pcall(read, self, ...)
      reading = false
      if not ok then error(err, 0) end
    end
  end
  cfg_load()
end

return M

end)()
local Mscenes = (function()  -- inlined lib/mscenes.lua
-- mscenes: scenes, scene morphing, and the safe-state snapshot — the
-- "remember this / go back to that" layer.
--
-- three features, one data model:
--   SCENES   8 slots, each a flat map { param_id = value } captured from the
--            live params. recall writes them back through params:set, so the
--            engine, the tape and the display all follow for free — a scene
--            is not a second source of truth, it's a photograph of the one
--            that exists.
--   MORPH    a crossfade between two ends, over the subset of params that
--            can be interpolated. B is a stored slot (scene_slot). A is the
--            sound you have now (LIVE, the default) or another stored slot
--            (scene_slot_a). one knob (scene_morph_amt) moves the whole
--            instrument along that line, both ways.
--   SAFE     one "last known good" snapshot + an instant restore. capture it
--            before you do something reckless (see the chaos throw below);
--            restore drops you straight back on your feet.
--
-- NOTHING here stores audio. scenes are control state only: a recall does not
-- bring back the take you have since overdubbed (that's what PSETs + the tape
-- wav are for, see mtape). that's also what makes it cheap — 8 slots is ~600
-- numbers, and a recall is ~80 params:set calls.
--
-- WHAT IS AND ISN'T IN A SCENE — the lists are right below and they are
-- deliberate. in: everything that shapes the sound of the take (window,
-- grain/clouds, stretch, tape loop, filter, delay, reverb, shimmer, voices).
-- out: the hardware/config layer (midi channel, keys, root note), the SYSTEM
-- levels (in/out/monitor/hp), the capture transports (rec, tape_rec), the
-- master STOP, the motion transport, and the UI selectors (slice cursor).
-- a scene changes how it sounds, never how it's plumbed or whether it's
-- running.
--
-- THE MORPH IS FRAME-COALESCED. scene_morph_amt's action only marks the sweep
-- dirty; M.tick() applies it at most once per redraw frame (the existing 15fps
-- clock — no new process, same modulation grid the gesture looper runs on).
-- a fast CC sweep would otherwise fire ~40 params x 128 CC steps at the engine
-- in a second; this caps it at 15 passes/s, and the per-param deadband below
-- drops the ones that aren't actually moving.

local floor, abs, min, max = math.floor, math.abs, math.min, math.max

local C            -- shared ctx, bound at init
local pget, clamp

local NUM_SLOTS = 8

-- ===========================================================================
-- the curated param lists
-- ===========================================================================
-- SCENE_RECALL_IDS is built from three ORDERED blocks, and recall/restore
-- walk it in order, so a scene lands in the order the engine wants it:
--
--   1 TIMBRE  the continuous voice: source blend, window, grain/clouds,
--             stretch shape, tape loop, voices
--   2 SPACE   the wet path: filter, drive, delay, reverb, shimmer
--   3 SWITCH  the discrete mode/type switches — LAST, on purpose: `mode`
--             respawns the SC voice, so switching it after everything else
--             means the new voice is BORN with the scene's params instead of
--             being born wrong and then jumped to them.
--
-- add a new mangle param to the right block and it joins scenes, morphs and
-- the safe snapshot at once (MOTION_IDS in mmotion is the same idea for the
-- gesture looper — the two lists are siblings, kept separate on purpose).

local TIMBRE_IDS = {
  -- source blend. NOT out_level: a scene must never rewrite your stage
  -- volume. (the safe snapshot does take it — see SAFE_EXTRA_IDS.)
  "mix", "sc_level", "cut_level",
  -- playback path + the output->buffer writers. resample only bites on
  -- the next armed take; regen and erode quietly rewrite the buffer, which
  -- is exactly why a scene should be able to pull them back to 0. wear is
  -- just a tone control and morphs freely. (orbit_* stays OUT of every
  -- list: it is a transport, like motion_*.)
  "dry_wet", "resample", "regen", "erode", "wear",
  -- window / scan
  "pos_start", "pos_end", "scan", "pos_jitter",
  -- grain + clouds (the granular character)
  "size", "density", "pitch", "spread", "pan", "grain_level",
  "grain_jitter", "grain_pitch_spread",
  "clouds_pos", "clouds_tex", "clouds_fb", "clouds_lofi",
  -- stretch shape (mode itself is a SWITCH, below)
  "warp_window", "warp_overlaps", "warp_rand",
  -- tape deck (loop bounds ride along, so a scene = a loop region too).
  -- cut_source is the record-SOURCE blend (dry..wet print) — continuous and
  -- slew-safe, so it morphs; it selects what WOULD be written, never writes.
  "tape_rate", "loop_start", "loop_end", "tape_pre", "tape_fade", "cut_source",
  -- polyphonic pad voices
  "voices", "voice_atk", "voice_rel", "pad_level",
  -- track 2 (four): the same knobs as track 1, so a scene keeps both
  "t2_level", "t2_pos_start", "t2_pos_end", "t2_scan", "t2_pitch", "t2_pan",
  "t2_pos_jitter", "t2_size", "t2_density", "t2_spread", "t2_grain_jitter",
  "t2_grain_pitch_spread", "t2_clouds_pos", "t2_clouds_tex", "t2_clouds_fb",
  "t2_clouds_lofi", "t2_warp_window", "t2_warp_overlaps", "t2_warp_rand",
  "t2_cutoff", "t2_resonance",
  -- NB: seq_slice (the PADS edit cursor) is deliberately NOT captured — it's a
  -- UI selector like scene_slot / motion_lane, not sound; a scene shouldn't
  -- move your cursor, and a morph must never lerp it across slices.
}

local SPACE_IDS = {
  "cutoff", "resonance", "drive",
  "delay_time", "delay_fb", "delay_mix", "dly_rev",
  "rev_decay", "rev_damp", "rev_size", "rev_early", "rev_moddepth",
  "rev_modfreq", "rev_low", "rev_mid", "rev_high", "rev_lowcut",
  "rev_highcut", "rev_mix",
  "shimmer", "shimmer_pitch", "shimmer_tone",
  -- COLOR and SPACE (four): each track's drive and crush, and its sends
  -- into the delay and the reverb
  "crush", "fx_dly", "fx_rev",
  "t2_drive", "t2_crush", "t2_fx_dly", "t2_fx_rev",
  "t3_drive", "t3_crush", "t3_fx_dly", "t3_fx_rev",
  "t4_drive", "t4_crush", "t4_fx_dly", "t4_fx_rev",
  -- THE EFFECT (four): each track's two effect knobs
  "effect_amt", "effect_rate", "t2_effect_amt", "t2_effect_rate",
  "t3_effect_amt", "t3_effect_rate", "t4_effect_amt", "t4_effect_rate",
  -- the second effect slot
  "effect2_amt", "effect2_rate", "t2_effect2_amt", "t2_effect2_rate",
  "t3_effect2_amt", "t3_effect2_rate", "t4_effect2_amt", "t4_effect2_rate",
}

local SWITCH_IDS = {
  "filt_type", "clouds_mode", "grain_shape",
  "delay_sync",   -- a scene remembers whether the delay follows the clock
  "win_beats",    -- ...and whether the window's length does
  "freeze", "pv_freeze", "tape_freeze", "pad_input",
  "tape_reverse",   -- tape direction is a LATCHING state under the punch law
  "vis_look",   -- the look the visuals show: a scene can bring its own
  "t2_filt_type", "t2_clouds_mode", "t2_grain_shape", "t2_pv_freeze",
  -- THE EFFECT (four): which effect each track's slot holds
  "effect", "t2_effect", "t3_effect", "t4_effect",
  "effect2", "t2_effect2", "t3_effect2", "t4_effect2",
  "t2_mode",   -- respawns track 2's voice
  "mode",   -- last of the last: this one respawns the voice
}

-- `tape_reverse` IS captured/recalled. The punch law makes TAPE K3 a LATCHING
-- toggle (a tap holds tape_reverse=1 until tapped again), so it is a real state —
-- and the direction lives ONLY here: Mtape.update_tape_rate does
-- `tape_rate * (tape_reverse==1 and -1 or 1)` with tape_rate kept positive, so a
-- backwards scene is NOT stored in tape_rate. It is in MORPH_EXCLUDE, though: a
-- morph must not flip the tape mid-sweep (a hard event, like a freeze).

local function append(dst, src)
  for i = 1, #src do dst[#dst + 1] = src[i] end
end

-- four: tracks 3 and 4 are classified exactly like track 2. Their ids
-- are track 2's with the number changed, appended (TIMBRE) or put beside
-- track 2's (SWITCH, so `mode` stays last of the last).
local function more_tracks(list)
  local out = {}
  for i = 1, #list do
    local id = list[i]
    out[#out + 1] = id
    local rest = id:match("^t2_(.+)$")
    if rest then
      out[#out + 1] = "t3_" .. rest
      out[#out + 1] = "t4_" .. rest
    end
  end
  return out
end
TIMBRE_IDS = more_tracks(TIMBRE_IDS)
SWITCH_IDS = more_tracks(SWITCH_IDS)
-- the sends are sound (what feeds what), so a scene keeps them and a morph
-- crosses them smoothly
for from = 1, 4 do
  for to = 1, 4 do
    if from ~= to then SPACE_IDS[#SPACE_IDS + 1] = "send_" .. from .. "_" .. to end
  end
end

local SCENE_RECALL_IDS = {}
append(SCENE_RECALL_IDS, TIMBRE_IDS)
append(SCENE_RECALL_IDS, SPACE_IDS)
append(SCENE_RECALL_IDS, SWITCH_IDS)

-- MORPH-SAFE = recall MINUS these. the rule, in one line: a morph never
-- flips a hold, never re-routes your notes, never writes the buffer, and
-- never changes the voice structure.
--   freeze / pv_freeze / tape_freeze  holds. crossing 0.5 mid-sweep is a
--     hard event, not a texture — recall the scene if you want the hold.
--   pad_input  note ROUTING. flipping it mid-sweep re-points the keyboard
--     and releases sounding pad voices.
--   resample / regen  the buffer writers. a sweep must stay undo-able, and
--     audio already committed to the buffer is not.
--   voices  the poly CAP. lerping it crosses integers, and every crossing
--     re-caps the engine's allocator — which steals (cuts) held pad notes
--     mid-sweep. structure, not texture: a recall sets it, a morph doesn't.
-- consequence, worth knowing: morph at amt=1 is NOT the same as recall(B) —
-- it moves the morph-safe subset only. sweep to 1, then K2 RCL to land the
-- rest. (the SCENE page says so: see M.unlanded + the "K2 TO LAND THE REST" cue.)
local MORPH_EXCLUDE = {
  freeze = true, pv_freeze = true, tape_freeze = true,
  pad_input = true, resample = true, regen = true, erode = true,
  voices = true,
  -- mode respawns the SC voice: crossing 0.5 mid-sweep is a click + a voice
  -- born with half-morphed params, not a texture. tape_reverse flips playback
  -- direction: also a hard event, not something to cross gradually. recall
  -- carries both; a morph leaves them (sweep to 1, then K2 RCL to land).
  mode = true, tape_reverse = true,
  -- track 2's mode and hold, for the same reasons as track 1's
  t2_mode = true, t2_pv_freeze = true,
  t3_mode = true, t3_pv_freeze = true, t4_mode = true, t4_pv_freeze = true,
  -- the window lock switching mid-sweep re-cuts the window in one frame
  win_beats = true,
  -- a look is a choice, not a texture: it changes at a recall, never mid-sweep
  vis_look = true,
  -- Clouds goes silent for a moment at a mode change: a recall lands it
  clouds_mode = true, t2_clouds_mode = true, t3_clouds_mode = true,
  t4_clouds_mode = true,
}

-- the two complementary halves of the recall list: what a morph carries, and
-- what it deliberately leaves behind (the latter drives the page's cue).
local SCENE_MORPH_IDS = {}
local MORPH_SKIPPED_IDS = {}
for i = 1, #SCENE_RECALL_IDS do
  local id = SCENE_RECALL_IDS[i]
  if MORPH_EXCLUDE[id] then
    MORPH_SKIPPED_IDS[#MORPH_SKIPPED_IDS + 1] = id
  else
    SCENE_MORPH_IDS[#SCENE_MORPH_IDS + 1] = id
  end
end

-- the safe snapshot is the recall set PLUS the master out: if a throw (or a
-- fat finger) moved your level, the rescue should bring that back too. it
-- still refuses the SYSTEM levels, the transports and stop_all — a restore
-- must never unmute you, re-arm a recording, or undo a STOP you're leaning on.
local SAFE_EXTRA_IDS = { "out_level" }
local SAFE_SNAPSHOT_IDS = {}
append(SAFE_SNAPSHOT_IDS, SAFE_EXTRA_IDS)
append(SAFE_SNAPSHOT_IDS, SCENE_RECALL_IDS)

-- NEVER capture the scene_* params themselves. scene_morph_amt's action
-- re-fires the morph, so a snapshot that restored it would immediately
-- overwrite everything it just restored. (they're also UI selectors — not
-- sound.) this is a note to whoever adds the next param to the lists above.

-- WHAT A SCENE DELIBERATELY LEAVES OUT — the other half of the recall list.
-- membership is TOTAL: test/test_control.lua asserts every param in the
-- paramset is in SCENE_RECALL_IDS or here, never neither and never both, so
-- a NEW param cannot silently miss the decision (the defect that recurred:
-- purity, FINE_IDS, RATE_IDS and these lists each missed a new param).
-- adding a param now FAILS the harness until it is placed on one side.
local SCENE_EXCLUDE = {
  -- the master + STOP: a scene must never rewrite stage volume or unmute
  -- (out_level is the ONE of these the safe snapshot takes — SAFE_EXTRA_IDS)
  "out_level", "stop_all",
  "mute_1", "mute_2", "mute_3", "mute_4",   -- a hand on the mixer, like STOP
  -- capture transports + write plumbing: a scene changes how it sounds,
  -- never whether or what it is recording
  "rec", "tape_rec", "rec_level", "pre_level", "clear_rec", "sample_file",
  "t2_file", "t3_file", "t4_file",   -- four: each track's own material
  "rec_wait", "rec_thresh", "rec_end", "rec_source", "rec_align", "rec_sync",
  "loop_sync",
  "take_undo", "undo_keep",
  "export_take", "take_tighten", "print_take", "print_len",
  "pad_chop", "pad_even",
  -- the autosampler: a pass that records, and how it plays the outboard
  "as_go", "as_port", "as_ch", "as_low", "as_high", "as_step", "as_vel",
  "as_hold", "as_wait", "as_tail", "as_floor",
  -- UI cursors + the per-pad lock EDITORS (the locks themselves ride the
  -- padlock pset, not scenes)
  "seq_slice", "pad_voice", "pad_pitch",
  "track_sel",   -- four: which track VOICE and FILTER address
  "route_sel",   -- four: the ROUTE grid's cursor
  -- config / keys
  "keys_enable", "midi_channel", "fader_ch", "fader_cc", "root_note", "kb_octave", "pitch_quant",
  -- the other machines' transports, and scene's own params (NEVER capture
  -- scene_*: scene_morph_amt's action re-fires the morph)
  "motion_rec", "motion_play", "motion_lane", "motion_depth", "motion_len",
  "motion_bars", "mod_focus",
  "orbit_on", "orbit_rate", "orbit_reach",
  -- the sequencer is a machine like the orbit: its run, and the pattern it
  -- generates, are left where they are by a scene
  "step_run", "step_div", "step_len", "step_fill", "step_order",
  "step_chance", "step_gate",
  -- the beat repeat: a hold you play, not a sound a scene keeps
  "beat_repeat", "repeat_div",
  -- the modulation out: routing to other gear, not sound
  "out_src", "out_midi", "out_ch", "out_cc", "out_crow",
  -- the visuals link: routing to a computer, not sound
  "osc_on", "osc_host", "osc_port", "vis_flash", "vis_midi",
  -- the modulators: machines too. A scene moves the knobs they ride on
  "lfo1_target", "lfo1_shape", "lfo1_period", "lfo1_rate", "lfo1_depth",
  "lfo2_target", "lfo2_shape", "lfo2_period", "lfo2_rate", "lfo2_depth",
  "lfo3_target", "lfo3_shape", "lfo3_period", "lfo3_rate", "lfo3_depth",
  "lfo4_target", "lfo4_shape", "lfo4_period", "lfo4_rate", "lfo4_depth",
  "lfo1_track", "lfo2_track", "lfo3_track", "lfo4_track",
  "scene_slot", "scene_slot_a", "scene_morph_amt", "scene_recall_mode", "scene_scope",
  "scene_glide",
  "scene_capture",
  "scene_recall", "scene_next", "scene_clear", "scene_safe_capture",
  "scene_safe_restore", "chaos_throw",
}

-- ===========================================================================
-- module state
-- ===========================================================================

local M = {
  slots = {},         -- slots[1..8] = { id = value } (nil = empty)
  safe = nil,         -- the safe snapshot, same shape
  pending = nil,      -- slot waiting on a quantized recall (nil = none)
  chaos_live = false, -- a chaos throw is currently held
  -- exposed for the harness's classification checks
  SCENE_RECALL_IDS = SCENE_RECALL_IDS,
  SCENE_EXCLUDE = SCENE_EXCLUDE,
  SCENE_MORPH_IDS = SCENE_MORPH_IDS,   -- what a fade moves (test/device/session.py)
}

local dirty = false      -- a morph is pending for the next tick
local morphing = false   -- re-entry guard (a param action must never recurse)
local last_sent = {}     -- morph: the last value/norm we pushed, per param
local pending_clock      -- the quantized-recall coroutine (nil = none)

-- THE MORPH'S A END. B is the selected slot. A is chosen by scene_slot_a:
-- 0 is LIVE, the sound you were making when the fade left 0, and 1..8 is a
-- stored slot. Both are taken on the rising edge out of 0 and dropped when
-- you come home to 0 (or when something else moves the instrument, see
-- invalidate):
--   morph_from  the live snapshot at that edge. Every fade has one: it is
--               the A end when A is LIVE, and the fallback for any id the
--               A slot (or B) does not carry.
--   morph_a     the A slot's table, LATCHED at that edge (nil = LIVE).
--               Changing scene_slot_a mid-fade does not move it: the fade
--               keeps the A it left from until it comes home, so it never
--               jumps, and 0 always lands on a stored sound. The new A
--               takes over at the next departure.
--
-- A = LIVE is the default, and it is the morph as it always was: "from HERE
-- to that slot" makes ONE stored scene immediately useful (capture, mangle,
-- slide back). A = a slot is the two-scene crossfader: E3 at 0 is A, at 1
-- is B, and a recorded sweep replays between two fixed sounds.
local morph_from = nil
local morph_a = nil
local morph_a_n = 0      -- the latched A's number, for the screen (0 = LIVE)
local morph_b_n = 0      -- the B the fade last aimed at (a clear refuses it)
-- A HAND KEEPS WHAT IT MOVES DURING A FADE (C7 of doc/signature-workflow.md).
-- fade_val holds the value the fade last wrote for each id. A param that no
-- longer holds it (or, before the first write, no longer holds the origin)
-- was moved by something else: a hand, MIDI, a motion lane, the rec stop.
-- It LEFT the fade (`left`): the fade skips it until it comes home, and home
-- leaves it where it was put. Capture by polling, never by wrapping `set`.
local fade_val = {}
local left = {}

local QUANT_BEATS = { 0, 1, 4 }   -- scene_recall_mode: NOW / BEAT / BAR
local GLIDE_MODE = 4              -- ...and GLIDE (scene_glide beats, then land)

-- ===========================================================================
-- param plumbing
-- ===========================================================================

local function lookup(id)
  return params.lookup[id] and params:lookup_param(id) or nil
end

local function slot_idx(slot)
  return clamp(floor((slot or pget("scene_slot", 1)) + 0.5), 1, NUM_SLOTS)
end

-- EVERY write in this module goes through here.
-- 1) params stay the single source of truth — we set the same ids the
--    encoders, keys and MIDI CCs set, and their actions do the engine work.
-- 2) the gesture looper is told the value came from US. mmotion captures by
--    polling for changes, so without this a scene jump or a morph sweep would
--    look exactly like forty hands on forty knobs and punch a lane for each.
--    scenes and motion stay orthogonal drivers: motion records the MORPH KNOB
--    (scene_morph_amt is in MOTION_IDS) and replays that — one lane, not forty.
local function pset(id, v)
  params:set(id, v)
  local mo = C.motion
  -- account for the RESOLVED value: a control quantizes what you hand it
  if mo and mo.account then mo.account(id) end
end

-- the morph's "already sent" memory is only valid while nothing else moves
-- the instrument, and its origin only while the sweep is the thing driving
-- the sound. reset_morph drops both, so the next amount move departs from
-- wherever we are by then. A capture or a clear needs only this: it changes
-- what a slot holds, and moves no param.
local function reset_morph()
  for k in pairs(last_sent) do last_sent[k] = nil end
  for k in pairs(fade_val) do fade_val[k] = nil end
  for k in pairs(left) do left[k] = nil end
  M.engaged = false
  morph_from = nil
  morph_a, morph_a_n, morph_b_n = nil, 0, 0
end

-- the INSTRUMENT moved (a recall, a restore, a chaos throw, a pset load):
-- reset the morph, and forget the key throws too. OPEN / WASH / INF / HEAL
-- each cache the values they displaced, to put back on un-latch; whatever
-- just moved the instrument moved those params as well, so un-latching would
-- write pre-recall values over the recall. A capture must NOT do this: it
-- moves nothing, and latch-OPEN, capture, un-latch is how a variant is built.
function M.invalidate()
  reset_morph()
  if C and C.throws_forget then C.throws_forget() end
end

-- ===========================================================================
-- feedback — every action says what it did, on screen AND in maiden
-- ===========================================================================
-- a scene action is far too easy to miss. capture moves ONE 13px box; recall
-- of the slot you just captured re-applies the sound you are ALREADY making,
-- so it is inaudible by definition; recall of an empty slot did nothing at all
-- and said nothing about it. that combination reads exactly like "the keys do
-- nothing, there's no sound" — which is what it was reported as, on a page
-- whose code was firing correctly the whole time. a performance page that
-- can't prove it worked is broken, whatever the code does.
--
-- so: one call, two audiences. `msg` is a chip on the page for ~1s; the detail
-- goes to maiden, where you can read the whole story after the fact (the
-- codebase already leans on bring-up prints for exactly this reason).
-- the "- SAME" variants are the important ones: they mean the action landed
-- and NOTHING moved, which is precisely why you can't hear anything.

local function say(msg, detail, slot)
  M.msg, M.msg_at, M.msg_slot = msg, C.frame, slot
  print("four: " .. (detail or msg))
end

local function say_recall(slot, n, moved)
  if moved == 0 then
    say("RECALL " .. slot .. " - SAME",
      "scene " .. slot .. " recalled — " .. n .. " params set, NONE moved: the"
      .. " instrument already sounds like this scene, which is why nothing"
      .. " changed. capture a DIFFERENT sound to another slot to hear a recall.",
      slot)
  else
    say("RECALL " .. slot,
      "scene " .. slot .. " recalled — " .. moved .. " of " .. n
      .. " params moved", slot)
  end
end

local function snapshot_ids(ids)
  local t, n = {}, 0
  for i = 1, #ids do
    local id = ids[i]
    if params.lookup[id] then
      t[id] = params:get(id)
      n = n + 1
    end
  end
  return t, n
end

-- region edges: two params that only mean something as a PAIR. setting them
-- one at a time means the consumer reads ONE new edge against ONE old one for
-- an instant — softcut can render up to a block of a region that is neither
-- the old nor the new one (and update_tape_loop's `hi-lo < 0.1` floor turns a
-- crossed pair into a 100ms loop, which jumps the head audibly). so: move the
-- edge that widens the region FIRST, and every intermediate contains a real
-- region instead of a bogus one. `start` key -> `end` key.
local EDGE_PAIRS = { pos_start = "pos_end", loop_start = "loop_end",
                     t2_pos_start = "t2_pos_end", t3_pos_start = "t3_pos_end",
                     t4_pos_start = "t4_pos_end" }
M.EDGE_PAIRS = EDGE_PAIRS   -- the harness asserts every _start/_end pair joins

-- A STORED window is clamped to the material before it is applied. Scenes
-- capture pos_start/pos_end verbatim, but the take may be shorter by the time
-- the scene comes back. The classic trap: capture a scene before recording
-- (window = the whole 60s buffer), record a 4s phrase (the rec-stop snaps the
-- window to it), recall the scene, and the window reopens over ~56 seconds of
-- nothing, so what you were listening to comes around once a minute. Beyond
-- C.take_len (the content high-water mark, from frame 0) there is silence BY
-- DEFINITION, so clamping a stored edge into it can only remove silence,
-- never sound. Only STORED values pass through here: a recall, a safe
-- restore, a morph target. Live values stay exact, so the encoder can still
-- open the window wherever it likes, and a sweep coming home restores the
-- origin verbatim (morph_from bypasses this).
--
-- The TAPE has the same trap: capture a scene while the tape is empty
-- (its loop 0..1), record a 4s pass (the loop closes around it), recall, and
-- the loop reopened over 60 seconds of nothing. A deck's material does not
-- start at 0, so the tape clamps to the EXTENT that was written (C.material:
-- lo, hi in the deck's own 0..1), and only when the stored loop is more than
-- TWICE the material and overlaps it. A loop's LENGTH is musical,
-- so a loop that is merely a little longer than what was
-- played into it is left alone; and a stored loop entirely elsewhere points
-- at something we cannot know about, and stays exactly as stored.
-- each track's window, by its track (C10 of doc/signature-workflow.md): a
-- track's window is clamped against that track's own take (C.take_of)
local WINDOW_IDS = { pos_start = 1, pos_end = 1,
  t2_pos_start = 2, t2_pos_end = 2, t3_pos_start = 3, t3_pos_end = 3,
  t4_pos_start = 4, t4_pos_end = 4 }
local EXTENT_OF = {
  loop_start = "tape", loop_end = "tape",
}
-- the same pairs, both ways round (shared with motion replay)
local PARTNER = {}
for a, b in pairs(EDGE_PAIRS) do PARTNER[a], PARTNER[b] = b, a end
M.PARTNER = PARTNER

local function clamp_stored(id, v, tbl)
  if v == nil then return v end
  local tr = WINDOW_IDS[id]
  if tr then
    local any, tl
    if C and C.take_of then any, tl = C.take_of(tr)
    elseif C then any, tl = C.wave_any, C.take_len end
    tl = (any and tl) or 0
    if tl <= 0.002 or tl >= 0.999 then return v end   -- no/full material: exact
    local cap = EDGE_PAIRS[id] == nil and tl or (tl - 0.002)
    return v < cap and v or cap
  end
  local key = EXTENT_OF[id]
  if not (key and tbl and C and C.material) then return v end
  local mlo, mhi = C.material(key)
  if not mlo then return v end                      -- nothing known: exact
  local is_start = EDGE_PAIRS[id] ~= nil
  local s, e = v, tbl[PARTNER[id]]
  if not is_start then s, e = e, v end
  if s == nil or e == nil or s > e then return v end
  if not (s < mhi and e > mlo) then return v end    -- elsewhere: exact
  if e - s < 2 * (mhi - mlo) then return v end       -- near the material: exact
  local ns, ne = max(s, mlo), min(e, mhi)
  if ne - ns < 0.002 then return v end
  return is_start and ns or ne
end

-- set one param and report whether the value actually MOVED. the count of
-- moved params is what tells a performer why a recall was silent: 0 moved
-- means the scene and the live sound are already the same.
local function set_moved(id, v)
  local before = params:get(id)
  pset(id, v)
  return params:get(id) ~= before and 1 or 0
end

-- apply a stored table, walking `ids` IN ORDER (timbre -> space -> switches;
-- see the list comment). params missing from the table are skipped, so a
-- scene captured by an older version still recalls what it does know.
-- returns: how many params were set, how many of them actually changed.
local function apply(tbl, ids)
  if not tbl then return 0, 0 end
  local n, moved = 0, 0
  local done                      -- edge partners already set (nil until needed)
  for i = 1, #ids do
    local id = ids[i]
    local v = clamp_stored(id, tbl[id], tbl)
    if v ~= nil and params.lookup[id] and not (done and done[id]) then
      local partner = EDGE_PAIRS[id]
      local pv = partner and clamp_stored(partner, tbl[partner], tbl)
      if pv ~= nil and params.lookup[partner] then
        -- outward edge first: if the new start moves LEFT it's the widening
        -- one, else the new end is
        if v < params:get(id) then
          moved = moved + set_moved(id, v) + set_moved(partner, pv)
        else
          moved = moved + set_moved(partner, pv) + set_moved(id, v)
        end
        done = done or {}
        done[partner] = true
        n = n + 2
      else
        moved = moved + set_moved(id, v)
        n = n + 1
      end
    end
  end
  M.invalidate()
  return n, moved
end

-- a recall still on its way (queued for a beat, or gliding) is forgotten by
-- anything that lands something else: another recall, the way back, a load
local function cancel_pending()
  if pending_clock then clock.cancel(pending_clock) end
  pending_clock, M.pending = nil, nil
  M.glide = nil
end

-- A scene LANDED (a recall, the way back): it IS the new LIVE. ONE place does
-- what every landing needs, because each landing path used to remember a
-- different subset of it:
--   the morph amount goes home. apply() has already dropped the sweep's
--     origin, so writing 0 moves nothing; left up, the rail lied and merely
--     selecting another slot at rest jumped the sound toward it.
--   a held chaos throw ENDS. its release restores ◄, and a recall made
--     mid-hold has just re-marked ◄ with the chaos state, so releasing the
--     footswitch would drag you back onto the madness over the scene you chose.
local function land(tbl, ids)
  local n, moved = apply(tbl, ids)
  M.chaos_live = false
  if pget("scene_morph_amt", 0) > 0 then pset("scene_morph_amt", 0) end
  return n, moved
end

-- the orbit's state (declared here: capture reads it)
local orbit = { on = false, live = false, leg_start = 0, leg_len = 1,
                wrote = nil, hand_at = nil }
local capture_free   -- defined below capture, which it calls

-- ===========================================================================
-- scenes — capture / recall / clear
-- ===========================================================================

-- capture the live state of SCENE_RECALL_IDS into a slot (default: the
-- selected one). overwrites without ceremony — like every other throw in this
-- instrument, the key does the thing.
-- slot 0 is the ◄ cell — the way back. capturing into it marks the
-- safe state, recalling it restores, clearing it forgets. the bank proper
-- stays 1..8; every ◄ caller branches here BEFORE slot_idx clamps.
local function is_back(slot)
  return floor((slot or pget("scene_slot", 1)) + 0.5) < 1
end

function M.capture(slot)
  if is_back(slot) then return M.safe_capture() end
  -- while the orbit runs it keeps re-aiming the selector, so a no-slot
  -- capture (SCENE K3, the scene_capture param) would land in whatever
  -- slot the wander just targeted and overwrite a scene it navigates by.
  -- redirect to the first empty slot; an EXPLICIT slot stays explicit.
  if slot == nil and orbit.on then return capture_free() end
  slot = slot_idx(slot)
  -- capture SCOPE (Octatrack-style): ALL = the whole mangle; FX = just the
  -- wet path (SPACE_IDS: filter, drive, delay, reverb, shimmer), so a slot
  -- becomes an effects preset that recalls and morphs OVER whatever material
  -- and voice you have at the time. apply() skips ids a slot does not carry,
  -- so partial slots were always legal; this makes them a supported gesture.
  local fx_only = floor(pget("scene_scope", 1) + 0.5) == 2
  local t, n = snapshot_ids(fx_only and SPACE_IDS or SCENE_RECALL_IDS)
  M.slots[slot] = t
  reset_morph()    -- the target's contents may have just changed under a sweep
  say("SAVED " .. slot .. (fx_only and " FX" or ""),
    "scene " .. slot .. " captured — " .. n .. (fx_only
      and " params (FX only: filter, drive, delay, reverb, shimmer)"
      or " params (the whole mangle: window, grain, stretch, tape loop,"
      .. " filter, FX, voices)"), slot)
  return true
end

-- recall a slot. scene_recall_mode decides when it lands (NOW / next BEAT /
-- next BAR). a queued recall replaces any other queued recall — last press
-- wins.
function M.recall(slot)
  if is_back(slot) then return M.safe_restore() end
  slot = slot_idx(slot)
  local scene = M.slots[slot]
  if not scene then
    -- an empty slot used to be a silent no-op, which reads as a dead key
    say("SLOT " .. slot .. " EMPTY",
      "scene " .. slot .. " is empty — nothing to recall. K3 (CAP) stores the"
      .. " current sound into it first.", slot)
    return false
  end
  local mode = floor(pget("scene_recall_mode", 1) + 0.5)
  local beats = QUANT_BEATS[mode] or 0
  cancel_pending()
  if mode == GLIDE_MODE then
    -- GLIDE: the morph sweeps there over scene_glide beats, then the scene
    -- LANDS (the holds, routing and writers a morph never moves included).
    -- An Octatrack-style crossfade instead of a jump. ◄ marks where it began.
    local b = pget("scene_glide", 4)
    if floor(pget("scene_slot", 1) + 0.5) ~= slot then pset("scene_slot", slot) end
    M.auto_safe()
    -- a held chaos throw ends HERE, as land() ends it for the other modes:
    -- ◄ now holds the chaos state, and the footswitch's release would restore
    -- it over the scene this glide is heading for
    M.chaos_live = false
    M.glide = { slot = slot, from = C.frame, a0 = pget("scene_morph_amt", 0),
      frames = math.max(1, floor(b * 60 / (C.tempo and C.tempo() or 120)
        * (C.FPS or 15) + 0.5)) }
    say("GLIDE " .. slot, "scene " .. slot .. " gliding in over " .. b
      .. " beats, then it lands", slot)
    return true
  end
  if beats > 0 then
    M.pending = slot
    say("QUEUED " .. slot,
      "scene " .. slot .. " queued — lands on the next "
      .. (beats > 1 and "bar" or "beat"), slot)
    -- ONE coroutine, always cancelled on replace / restore / cleanup (the
    -- norns clock-race gotcha: a timer resuming a dead thread wedges clock)
    pending_clock = clock.run(function()
      clock.sync(beats)
      pending_clock, M.pending = nil, nil
      M.auto_safe()   -- ◄ = where you just were, even for a queued landing
      say_recall(slot, land(M.slots[slot], SCENE_RECALL_IDS))
    end)
    return true
  end
  -- every commit auto-captures the pre-state into the ◄ cell — an
  -- undo that never needed arming. (quiet: the recall is the news here.)
  M.auto_safe()
  say_recall(slot, land(scene, SCENE_RECALL_IDS))
  return true
end

-- advance to the NEXT FILLED slot (cycling, skipping empties) and recall it —
-- the stomp-through-a-set gesture (scene_next, MIDI-map a footswitch). moves
-- the ONE selector so the page/grid/morph all follow, then recalls through
-- the normal path (BEAT/BAR quantize and auto-safe both apply).
function M.next()
  -- from the ◄ cell the next slot is 1 (slot_idx would clamp ◄ to 1 and
  -- start the search at 2)
  local start = is_back() and 0 or slot_idx()
  for i = 1, NUM_SLOTS do
    local s = ((start - 1 + i) % NUM_SLOTS) + 1
    if M.slots[s] then
      params:set("scene_slot", s)
      return M.recall(s)
    end
  end
  say("NO SCENES", "no filled slots to advance to — CAP stores one first")
  return false
end

-- capture into the first EMPTY slot (the orbit's CAP: bottling a found
-- sound must never overwrite a scene the wander is navigating by)
capture_free = function()
  for s = 1, NUM_SLOTS do
    if not M.slots[s] then return M.capture(s) end
  end
  say("BANK FULL",
    "all 8 slots hold scenes — clear one to keep the orbit's find")
  return false
end

function M.clear(slot)
  if is_back(slot) then
    local had = M.safe ~= nil
    M.safe = nil
    say(had and "CLEARED <" or "< EMPTY",
      had and "the ◄ way-back state was cleared"
      or "the ◄ cell was already empty")
    return true
  end
  -- the orbit re-aims the selector every leg, so a no-slot clear (the
  -- scene_clear footswitch) would erase whatever the wander picked. The key
  -- path passes the slot it pressed on; an unaddressed clear refuses.
  if slot == nil and orbit.on then
    say("ORBIT RUNNING", "the orbit is moving the selector — stop it (orbit run)"
      .. " before clearing a slot from the footswitch")
    return false
  end
  slot = slot_idx(slot)
  -- an engaged fade departed from its A slot and aims at its B: clearing
  -- either strands the way home (C9 of doc/signature-workflow.md)
  if morph_from and (slot == morph_a_n or slot == morph_b_n) then
    say("FADE ON " .. slot .. ": HOME FIRST", "scene " .. slot .. " is an end of the"
      .. " fade that is up: bring the fade home (K1+E3 to 0), then clear it", slot)
    return false
  end
  local had = M.slots[slot] ~= nil
  M.slots[slot] = nil   -- in place: the grid and the page read this table
  if M.pending == slot or (M.glide and M.glide.slot == slot) then
    cancel_pending()
  end
  reset_morph()
  say(had and ("CLEARED " .. slot) or ("SLOT " .. slot .. " EMPTY"),
    had and ("scene " .. slot .. " cleared") or
    ("scene " .. slot .. " was already empty"), slot)
  return true
end

-- ===========================================================================
-- morph: a crossfade from A (LIVE or a slot) to B (a slot), one knob
-- ===========================================================================
-- continuous params interpolate in the controlspec's OWN (warped) space
-- (ctx.warped_lerp): cutoff 20 -> 20000 is exponential, so a raw lerp would
-- sit at "nearly open" for the whole second half of the sweep.
-- numbers (voices, warp_overlaps) lerp and land on integers; options and
-- binaries can't be half-switched, so they flip at the midpoint (amt >= 0.5).

-- An option or a binary crosses ONCE (C8 of the plan): it goes to B above
-- 0.55 and back to A below 0.45. Between the two it keeps `last`, what the
-- fade last wrote, so a fade rocked about the middle does not switch an
-- effect or a filter type on and off. The ends are exact.
local BAND_LO, BAND_HI = 0.45, 0.55
local function band(va, vb, amt, last)
  if amt >= BAND_HI then return vb end
  if amt <= BAND_LO then return va end
  if last == va or last == vb then return last end
  return amt < 0.5 and va or vb
end

local function morph_value(id, va, vb, amt, last)
  local p = lookup(id)
  if not p then return nil end
  local cs = p.controlspec
  if cs then
    -- the normalized target doubles as the deadband key below: if a param is
    -- identical in A and B, tn never moves and it never gets sent at all
    return C.warped_lerp(cs, va, vb, amt)
  end
  if p.count then                                  -- option: midpoint band
    return band(va, vb, amt, last)
  end
  if p.min and p.max then                          -- number: lerp -> integer
    return clamp(floor(va + (vb - va) * amt + 0.5), p.min, p.max)
  end
  return band(va, vb, amt, last)                   -- binary / unknown
end

-- normalized deadband: a param must move at least this much (of its full
-- range) before we re-send it. kills duplicate engine commands on a sweep
-- without being coarse enough to see or hear.
local MORPH_EPS = 1 / 400

-- the sweep in progress, read by emit(). Module state rather than a closure
-- per call: the morph runs every frame while a sweep or the orbit moves, and
-- this is the hot path that is meant to allocate nothing.
local sw_amt, sw_force = 0, false
local pair_done = {}       -- edge partners already written this pass (reused)

-- the A end of one id: the latched A slot's stored value (clamped to the
-- material like every stored value), or the live origin when A is LIVE or
-- the A slot does not carry it (an FX-only slot). nil = no such param.
local function end_a(id)
  local live = morph_from[id]
  if live == nil then return nil end
  local A = morph_a
  if A and A[id] ~= nil then return clamp_stored(id, A[id], A) end
  return live
end

-- one param's step of the sweep. `va` comes from end_a; `vb` is B's stored
-- value, already clamped to the material (clamp_stored).
--   va nil              the origin never had it (an older capture): skip.
--   vb nil              B does not carry it (an FX-only slot, a partial
--                       preset slot). Its B end is the live origin, as it is
--                       for a param an Octatrack scene does not lock. With A
--                       LIVE that line runs from the origin to itself: an id
--                       this sweep already moved under an earlier aim goes
--                       home, any other is skipped.
--   va == vb == origin  the Octatrack rule: a param both ends leave where
--                       the sound had it is not the morph's to move, so a
--                       hand riding it stays live, even through the forced
--                       ends. An id this sweep already displaced (last_sent)
--                       still tracks the line. Two SLOTS that agree on a
--                       value the live sound does not have do move it: the
--                       fader is between those two scenes.
-- has `id` left the fade (C7)? It has when it no longer holds what the fade
-- last wrote, or the origin before the fade wrote it.
local function gone(id)
  if left[id] then return true end
  local ref = fade_val[id]
  if ref == nil then ref = morph_from[id] end
  if ref ~= nil and params.lookup[id] and params:get(id) ~= ref then
    left[id] = true
    return true
  end
  return false
end
M.left = left   -- the harness reads it

local function emit(id, va, vb)
  if va == nil or not params.lookup[id] then return end
  if gone(id) then return end
  local live = morph_from[id]
  if vb == nil then vb = live end
  if va == vb and vb == live and last_sent[id] == nil then return end
  local v, tn = morph_value(id, va, vb, sw_amt, last_sent[id])
  if v == nil then return end
  local key = tn or v          -- continuous: compare norms; discrete: values
  local last = last_sent[id]
  local fire = sw_force or last == nil
    or (tn and abs(tn - last) >= MORPH_EPS)
    or (not tn and v ~= last)
  if fire then
    pset(id, v)
    last_sent[id] = key
    fade_val[id] = params:get(id)   -- the resolved value: a control quantizes
  end
end

-- the A slot the NEXT fade latches when it leaves 0 (0 = LIVE): the selected
-- scene_slot_a when it holds a scene, LIVE when that slot is empty. And LIVE
-- whenever a machine, not the fader, takes the amount out of 0:
--   the orbit   every leg parks and departs again, so an A slot would pull
--               the sound back to A at the start of each leg. The wander
--               always departs from the sound the last leg found.
--   K2          a PEEK borrows B from the sound you have, and its release
--               comes back to it; a GLIDE recall crossfades from the sound
--               you have into B. K2 works as it always did. (Started while
--               a fade is engaged, both continue that fade instead.)
local function a_next()
  if orbit.on or C.peek_on or C.peek_back or M.glide then return 0 end
  local n = clamp(floor(pget("scene_slot_a", 0) + 0.5), 0, NUM_SLOTS)
  if n >= 1 and M.slots[n] then return n end
  return 0
end

-- the A end the SCENE rail names (0 = LIVE): the latched one while a fade is
-- engaged, else the one the next departure would latch
function M.a_end()
  if morph_from then return morph_a_n end
  return a_next()
end

-- morph `amt` (0..1) of the way from A toward `slot` (B).
--   amt 0   A: the sound you had when you started sweeping (A = LIVE), or
--           the A slot's stored sound (exactly, for the morph-safe subset)
--   amt 1   B's stored sound (exactly, for the morph-safe subset)
-- returns false when the slot is empty, or when there's nothing to do (parked
-- at 0 with no sweep in progress — at rest the sound is just the sound).
-- With A = a slot, the first move out of 0 brings A in at once: at rest the
-- sound is whatever you play, and A is where the fader's line starts.
function M.morph(slot, amt)
  if morphing then return false end    -- a param action can never recurse in
  amt = clamp(amt or 0, 0, 1)
  local B = (not is_back(slot)) and M.slots[slot_idx(slot)] or nil
  if not B then
    -- ◄ / an empty slot can't be swept TOWARD — but a sweep already engaged
    -- must still come HOME: re-aim the selector at a dead target mid-sweep
    -- and turning the knob to 0 restores the A end of everything this sweep
    -- displaced (exactly the ids in last_sent). without this the sweep was
    -- stranded: neither able to move nor to land home.
    if not (amt <= 0 and morph_from) then return false end
    morphing = true
    -- walk the morph list IN ORDER (like every other writer here), restoring
    -- only the ids this sweep displaced (the last_sent filter). the region
    -- pairs go WIDENING EDGE FIRST — the same rule apply() and the sweep
    -- follow: restored in bare list order a pair can cross for one write,
    -- and a crossed pair hits the 100ms loop floor and jumps the head.
    local function back(k)
      if last_sent[k] ~= nil and params.lookup[k] and not gone(k) then
        local v = end_a(k)
        if v ~= nil then pset(k, v) end
      end
    end
    local rdone
    for i = 1, #SCENE_MORPH_IDS do
      local id = SCENE_MORPH_IDS[i]
      if not (rdone and rdone[id]) then
        local partner = EDGE_PAIRS[id]
        local va = partner and params.lookup[id] and params.lookup[partner]
          and end_a(id) or nil
        if va and end_a(partner) ~= nil then
          -- a pair moves together or not at all: one edge left, both stay
          if gone(id) or gone(partner) then
            left[id], left[partner] = true, true
          elseif va < params:get(id) then back(id); back(partner)
          else back(partner); back(id) end
          rdone = rdone or {}
          rdone[partner] = true
        else
          back(id)
        end
      end
    end
    morphing = false
    M.invalidate()   -- forget the sweep: we are home
    return true
  end
  if amt <= 0 and not morph_from then return false end
  if not morph_from then
    -- rising edge out of 0: where we are RIGHT NOW is the live origin, and
    -- the A end is latched here too, both held until the fade comes home
    morph_from = snapshot_ids(SCENE_MORPH_IDS)
    morph_a_n = a_next()
    morph_a = morph_a_n >= 1 and M.slots[morph_a_n] or nil
  end
  morph_b_n = slot_idx(slot)
  -- at the ends, land EXACTLY on the stored values (no deadband rounding)
  sw_amt, sw_force = amt, amt <= 0 or amt >= 1
  morphing = true
  local ids = SCENE_MORPH_IDS
  for k in pairs(pair_done) do pair_done[k] = nil end
  for i = 1, #ids do
    local id = ids[i]
    if not pair_done[id] then
      local partner = EDGE_PAIRS[id]
      local va = end_a(id)
      local vb = clamp_stored(id, B[id], B)   -- a stored loop aims at material
      if partner and params.lookup[partner] and va ~= nil
          and morph_from[partner] ~= nil and (gone(id) or gone(partner)) then
        -- a pair moves together or not at all: one edge left, both stay
        left[id], left[partner] = true, true
        pair_done[partner] = true
      elseif partner and params.lookup[partner] and va ~= nil
          and morph_from[partner] ~= nil then
        -- a REGION's two edges move together, and the WIDENING one goes first —
        -- the same rule apply() follows, and for the same reason: written in
        -- list order a sweep can momentarily cross the pair, and a crossed pair
        -- hits the 100ms minimum-length floor, which jumps the softcut head.
        -- The morph runs this 15 times a second, so it meets the hazard far
        -- more often than a recall does.
        local pa, pb = end_a(partner), clamp_stored(partner, B[partner], B)
        local nv = morph_value(id, va, vb == nil and morph_from[id] or vb, amt)
        if nv ~= nil and nv < params:get(id) then
          emit(id, va, vb); emit(partner, pa, pb)
        else
          emit(partner, pa, pb); emit(id, va, vb)
        end
        pair_done[partner] = true
      else
        emit(id, va, vb)
      end
    end
  end
  morphing = false
  M.engaged = amt > 0   -- the morph is what's driving the sound... unless home
  if amt <= 0 then
    -- home again, on A: exactly where you started (A = LIVE), or the A
    -- slot's sound. forget both ends so the NEXT sweep departs from wherever
    -- you are by then with the A selected by then, and forget what we sent
    -- so it re-asserts from scratch.
    morph_from = nil
    morph_a, morph_a_n, morph_b_n = nil, 0, 0
    for k in pairs(last_sent) do last_sent[k] = nil end
    for k in pairs(fade_val) do fade_val[k] = nil end
    for k in pairs(left) do left[k] = nil end
  end
  return true
end

-- does this slot hold state a MORPH can't carry? (the MORPH_SKIPPED_IDS —
-- holds, routing, buffer writers, the voice cap.) true = the sweep has
-- arrived but those are still sitting where you left them, and only a K2
-- recall lands them. drives the SCENE page's "K2 TO LAND THE REST" cue, which
-- exists so `morph(1) ~= recall(B)` is visible instead of mysterious. The ◄
-- cell is never "unlanded": K2 there is the way back, not a landing.
function M.unlanded(slot)
  if is_back(slot) then return false end
  local scene = M.slots[slot_idx(slot)]
  if not scene then return false end
  for i = 1, #MORPH_SKIPPED_IDS do
    local id = MORPH_SKIPPED_IDS[i]
    local v = scene[id]
    if v ~= nil and params.lookup[id]
        and abs(params:get(id) - v) > 1e-6 then
      return true
    end
  end
  return false
end

-- scene_morph_amt's action calls this: mark the sweep dirty and let the next
-- frame do the work (see the coalescing note at the top).
function M.touch()
  dirty = true
end

-- ===========================================================================
-- orbit: the instrument wanders the scene bank by itself
-- ===========================================================================
-- one leg at a time: pick a filled slot, ramp the morph partway toward it
-- (orbit_reach) over orbit_drift seconds, park there, pick another. parking
-- means dropping the sweep origin without applying anything, so the next leg
-- departs from the in-between sound the last one found. everything goes
-- through the same scene_slot and scene_morph_amt params a hand would use:
-- the SCENE page shows the wander live, and CAP bottles any moment of it.
-- with one filled slot each leg halves the remaining distance toward it;
-- with none the orbit idles. math.random stays out of the draw path.
-- While it runs, the A end is LIVE whatever scene_slot_a says (a_next): a
-- leg departs from the sound the last one found, never from a fixed A.
-- Its drift and reach live in PARAMS (orbit), its run switch on the grid.

-- (`orbit` itself is declared above capture, which reads it)

-- parking moves no param: it only drops the sweep's origin, so the next leg
-- departs from wherever this one left the sound. It must not forget the key
-- throws (it is not the instrument moving), and it writes the morph amount
-- home silently (with no origin, 0 sends nothing).
local function orbit_park()
  reset_morph()
  pset("scene_morph_amt", 0)
end

local orbit_filled = {}   -- reused: the orbit looks for a target every leg
local function orbit_new_leg()
  local filled, cur = orbit_filled, slot_idx()
  for k = #filled, 1, -1 do filled[k] = nil end
  for s = 1, NUM_SLOTS do
    if M.slots[s] and s ~= cur then filled[#filled + 1] = s end
  end
  if #filled == 0 and not M.slots[cur] then return false end
  local target = #filled > 0 and filled[math.random(#filled)] or cur
  pset("scene_slot", target)
  orbit.leg_start = C.frame
  orbit.leg_len = math.max(2, math.floor(pget("orbit_rate", 12) * (C.FPS or 15)))
  return true
end

function M.orbit_set(on)
  orbit.on = on
  orbit.wrote, orbit.hand_at = nil, nil
  orbit_park()                 -- depart from (or stop on) wherever we stand
  orbit.live = on and orbit_new_leg()
end

-- the orbit YIELDS to anything else that moves the morph amount: a hand on
-- K1+E1 or a MIDI fader, the RCL peek, a glide, a landing. It watches for a
-- value it did not write, stands still while that keeps happening, and two
-- seconds after it stops parks where the other hand left the sound and
-- starts a fresh leg from there.
local ORBIT_YIELD = 2          -- seconds of quiet before the wander resumes

-- `live` = a leg is actually running. With no filled slot to aim at there is
-- no leg: the orbit looks for a target each frame and touches nothing.
local function orbit_tick()
  if not orbit.on then return end
  local amt = pget("scene_morph_amt", 0)
  -- a held RCL peek parks the amount at 1 and stops moving it, but its
  -- release still needs the sweep's origin to go home: until it is home, the
  -- peek is a hand on the morph even while the value stands still
  if (orbit.wrote ~= nil and abs(amt - orbit.wrote) > 1e-9)
      or C.peek_on or C.peek_back then
    orbit.hand_at = C.frame
  end
  orbit.wrote = amt
  if orbit.hand_at then
    if C.frame - orbit.hand_at < ORBIT_YIELD * (C.FPS or 15) then return end
    orbit.hand_at = nil
    orbit_park()
    orbit.wrote = pget("scene_morph_amt", 0)
    orbit.live = false
  end
  local t = (C.frame - orbit.leg_start) / orbit.leg_len
  if t >= 1 or not orbit.live then
    if orbit.live then orbit_park() end
    orbit.live = orbit_new_leg()
    orbit.wrote = pget("scene_morph_amt", 0)
    if not orbit.live then return end
    t = 0
  end
  pset("scene_morph_amt", pget("orbit_reach", 0.5) * t)
  orbit.wrote = pget("scene_morph_amt", 0)
end

-- a GLIDE in progress: ramp the morph from where it stood to 1 over its
-- frames, then land the scene. A hand on the morph or the selector mid-glide
-- wins: the glide stops and the sound stays where the hand put it.
local function glide_tick()
  local g = M.glide
  if not g then return end
  if floor(pget("scene_slot", 1) + 0.5) ~= g.slot
      or (g.wrote ~= nil and abs(pget("scene_morph_amt", 0) - g.wrote) > 1e-9) then
    M.glide = nil
    say("GLIDE STOPPED", "the glide to scene " .. g.slot .. " stopped: the morph"
      .. " or the selected slot was moved by hand", g.slot)
    return
  end
  local t = (C.frame - g.from) / g.frames
  if t >= 1 then
    M.glide = nil
    say_recall(g.slot, land(M.slots[g.slot], SCENE_RECALL_IDS))
    return
  end
  pset("scene_morph_amt", g.a0 + (1 - g.a0) * t)
  g.wrote = pget("scene_morph_amt", 0)
end

-- one per redraw frame, from the existing 15fps clock in four.lua.
-- the target (B) is simply the SELECTED slot, the same one K2 recalls and
-- K3 captures into. one selector, three jobs. The A end is scene_slot_a,
-- read once, when the fade leaves 0 (a_next).
function M.tick()
  glide_tick()                 -- a glide moves the morph before the orbit looks
  orbit_tick()                 -- may set the morph params, marking dirty
  if not dirty then return end
  dirty = false
  M.morph(pget("scene_slot", 1), pget("scene_morph_amt", 0))
end

-- ===========================================================================
-- safe snapshot — the undo for live experimentation
-- ===========================================================================

function M.safe_capture()
  local t, n = snapshot_ids(SAFE_SNAPSHOT_IDS)
  M.safe = t
  say("MARKED <",
    "way-back state marked — " .. n .. " params. select the ◄ cell and K2"
    .. " brings this exact sound back.")
  return true
end

-- the quiet version: every commit recall / chaos throw parks the pre-state
-- in ◄ without stealing the headline from the action itself
function M.auto_safe()
  M.safe = snapshot_ids(SAFE_SNAPSHOT_IDS)
end

-- back to the last known good state, now. control state only: it does not
-- touch the buffer, the tape audio, or held voices — this is an undo for
-- knobs, not a panic mute (K1+K2 STOP is the mute, and it stays yours).
function M.safe_restore()
  if not M.safe then
    say("NO SAFE STATE",
      "no safe state marked yet — select the ◄ cell and K3 (CAP) marks one;"
      .. " every recall and every chaos throw also marks it for you")
    return false
  end
  cancel_pending()   -- a queued recall must not undo the rescue a beat later
  local n, moved = land(M.safe, SAFE_SNAPSHOT_IDS)
  say(moved == 0 and "UNDO - SAME" or "UNDO",
    "safe state restored — " .. moved .. " of " .. n .. " params moved")
  return true
end

-- ===========================================================================
-- chaos throw — hold for madness, release for safety
-- ===========================================================================
-- chaos_throw is a MOMENTARY param: press throws, release restores the safe
-- snapshot. map it to a footswitch or hit the grid pad. the throw is bounded
-- per-param in NORMALIZED space, so it lands somewhere wild but never
-- somewhere silent, and (like the morph) it never touches rec/resample/regen
-- or the levels — everything it does is undo-able, which is the whole point.
-- math.random lives here and nowhere near the draw path: the seeded render
-- suite never calls it, so the pages' RNG stream is untouched.

local CHAOS = {
  { "pos_jitter", 0.35, 1.00 },
  { "density", 0.55, 1.00 },
  { "size", 0.00, 0.45 },
  { "grain_jitter", 0.30, 1.00 },
  { "grain_pitch_spread", 0.20, 0.90 },
  { "clouds_tex", 0.00, 1.00 },
  { "clouds_fb", 0.20, 0.70 },
  { "resonance", 0.40, 0.95 },
  { "drive", 0.20, 0.80 },
  { "delay_fb", 0.50, 0.95 },
  { "delay_mix", 0.30, 0.90 },
  { "rev_mix", 0.30, 0.90 },
  { "shimmer", 0.20, 0.90 },
  { "warp_rand", 0.30, 1.00 },
}
M.CHAOS = CHAOS   -- exposed so the harness can flag an entry for a dead param

-- scan is bipolar — normalized 0.5 is STOPPED. throw it to one side or the
-- other so chaos always keeps moving.
local SCAN_FWD = { 0.62, 0.95 }
local SCAN_REV = { 0.05, 0.38 }

local function set_norm(id, n)
  local p = lookup(id)
  if p and p.controlspec then pset(id, p.controlspec:map(clamp(n, 0, 1))) end
end

local function throw(id, lo, hi)
  set_norm(id, lo + math.random() * (hi - lo))
end

function M.chaos()
  -- never strand the performer: the throw parks where-you-were in ◄, so the
  -- release always has somewhere to land (and ◄ is always the LAST ground)
  M.auto_safe()
  for i = 1, #CHAOS do
    local c = CHAOS[i]
    throw(c[1], c[2], c[3])
  end
  local s = math.random() < 0.5 and SCAN_REV or SCAN_FWD
  throw("scan", s[1], s[2])
  M.invalidate()
  M.chaos_live = true
  say("CHAOS", "chaos thrown — release to land back on the safe state")
  return true
end

-- the release edge. it only acts when a throw is actually live, so a stray 0
-- (params:bang at init, a pset read) can never restore out of nowhere.
function M.chaos_release()
  if not M.chaos_live then return false end
  M.chaos_live = false
  return M.safe_restore()
end

-- ===========================================================================
-- persistence — rides along with the PSET
-- ===========================================================================
-- the scene bank + the safe snapshot save as a plain lua table next to the
-- pset, in the same data/ folder the tape audio uses. four.lua's
-- action_write/read/delete call BOTH modules (mtape does the audio, we do
-- the state) — that hook is shared, never replaced.

local function path_for(number)
  return norns.state.data .. "scenes-" .. number .. ".lua"
end

function M.pset_write(number)
  local ok, err = pcall(tab.save,
    { v = 1, slots = M.slots, safe = M.safe }, path_for(number))
  if not ok then print("four: scene save failed — " .. tostring(err)) end
end

function M.pset_read(number)
  -- a pset LOAD is authoritative: params:read() has just restored the VALUES
  -- the sound actually had — and in doing so re-set scene_morph_amt, which
  -- fired touch() and armed a sweep. drop it. re-deriving the morph here would
  -- overwrite any param the performer hand-tweaked AFTER their last morph move
  -- and saved, one frame after the load, silently. the morph re-engages on the
  -- next move of the knob. (this runs from action_read, i.e. after the values.)
  dirty = false
  -- a LOAD is authoritative: cancel any queued (BEAT/BAR) recall FIRST, before
  -- any early return — otherwise a coroutine armed just before the load survives
  -- and fires an old slot over the freshly loaded session a beat later.
  cancel_pending()
  -- the load is authoritative even when NO scene file follows: a morph_from /
  -- last_sent left engaged would re-derive the morph from the PRE-load sound
  -- on the next knob move. (covers every path below, including the early
  -- returns — nothing after this touches the morph state again.)
  M.invalidate()
  local path = path_for(number)
  -- no scene file (a pset from before scenes existed): leave the bank alone,
  -- exactly like mtape leaves the tape audio alone when there's no wav
  if not util.file_exists(path) then return end
  local ok, t = pcall(tab.load, path)
  if not (ok and type(t) == "table" and type(t.slots) == "table") then
    print("four: scene file unreadable — " .. tostring(t))
    return
  end
  for i = 1, NUM_SLOTS do
    M.slots[i] = type(t.slots[i]) == "table" and t.slots[i] or nil
  end
  -- CLEAR safe when the loaded pset has none, like the slots — otherwise the
  -- previous session's ◄/safe-state bleeds into this one and its recall jumps
  -- the instrument to a sound this session never captured.
  M.safe = type(t.safe) == "table" and t.safe or nil
end

function M.pset_delete(number)
  os.remove(path_for(number))
end

-- ===========================================================================
-- lifecycle
-- ===========================================================================

function M.init(ctx)
  C = ctx
  pget, clamp = ctx.pget, ctx.clamp
  ctx.scene = M          -- the module, like ctx.motion. its bank is M.slots,
                         -- mutated in place and never reassigned
end

function M.cleanup()
  cancel_pending()
end

return M

end)()
local Mwav = (function()  -- inlined lib/mwav.lua
-- mwav: the wav files lua reads and writes. Lua cannot read an SC or softcut
-- buffer, so every picture and every analysis of audio in this instrument
-- comes from a FILE: a loaded sample, a PSET's saved take, or a dump of the
-- live take (ctx.take_to_wav). This module is that layer:
--   the RIFF walker and the sample decoders (16/24/32-bit PCM, 32-bit float,
--     the extensible header resolved to its real format)
--   the async fill queue that paints 128-bin strips from a file
--   the sample-rate converter (a windowed sinc), so an off-rate file loads in
--     tune
--   onset and transient detection (TIGHTEN, CHOP)
--   the stereo interleave for exports
-- It knows nothing about the screen: mpages owns the strips and hands their
-- bins tables in.

local floor, sin, cos = math.floor, math.sin, math.cos
local abs, min, max = math.abs, math.min, math.max

local clamp
local SERVER_SR

local M = {}

-- like every lib module: bound to the shared ctx (the server rate, clamp)
function M.init(ctx)
  SERVER_SR, clamp = ctx.SERVER_SR, ctx.clamp
end

-- THE FILL QUEUE: an async waveform read. The FAST part (the header, so the
-- caller knows the duration at once) runs in queue_fill; the slow per-bin peak
-- read is deferred to load_tick (BINS_PER_TICK bins a frame on the redraw
-- clock), so a long file draws IN over about a second instead of freezing the
-- screen. ONE queue serves every strip — the take, the tape
-- — so a pset restore can repaint all of them; a new fill for the SAME bins
-- table supersedes the queued one, and fills for different targets coexist.
-- cancel_fill stops only ITS strip's fill (a CLR must stop the very repaint
-- that would redraw what it just erased, and nothing else).
local fills = {}
local BINS_PER_TICK = 10
function M.cancel_fill(bins)
  for i = #fills, 1, -1 do
    if fills[i].bins == bins then
      pcall(function() fills[i].f:close() end)
      table.remove(fills, i)
    end
  end
end
local function cancel_all_fills()
  for i = #fills, 1, -1 do
    pcall(function() fills[i].f:close() end)
    fills[i] = nil
  end
end

-- walk a RIFF/WAVE file to its fmt + data chunks, leaving f positioned at the
-- data. returns afmt, ch, bits, sr, dpos, dlen — or nil if not RIFF/WAVE.
-- shared by every reader below (the previews, the converter, the scans and
-- open_pcm_mono for the export).
local function riff_parse(f)
  local hdr = f:read(12)
  if not hdr or #hdr < 12 or hdr:sub(1, 4) ~= "RIFF" or hdr:sub(9, 12) ~= "WAVE" then
    return nil
  end
  local afmt, ch, bits, sr, dpos, dlen = 1, 1, 16, 48000, nil, 0
  while true do
    local c = f:read(8)
    if not c or #c < 8 then break end
    local id, sz = c:sub(1, 4), string.unpack("<I4", c, 5)
    if id == "fmt " then
      local fmt = f:read(sz)
      if not fmt or #fmt < 16 then break end
      afmt = string.unpack("<I2", fmt, 1)     -- 1 = PCM int, 3 = IEEE float
      ch = string.unpack("<I2", fmt, 3)
      sr = string.unpack("<I4", fmt, 5)
      bits = string.unpack("<I2", fmt, 15)
      -- WAVE_FORMAT_EXTENSIBLE: the real format is the first two bytes of the
      -- SubFormat GUID (1 PCM, 3 float). ffmpeg and SoX write this header for
      -- anything over 16 bits, so a float render arrives looking like PCM;
      -- decoding its float bits as int32 drew noise and converted to buzz.
      if afmt == 0xFFFE and #fmt >= 26 then
        afmt = string.unpack("<I2", fmt, 25)
      end
      -- a frame wider than the stated depth (24 valid bits stored in 32):
      -- read the CONTAINER, whose top bits hold the sample. blockAlign is the
      -- frame size the file actually uses.
      local ba = string.unpack("<I2", fmt, 13)
      if ch > 0 and ba > ch * (bits // 8) and ba % ch == 0 then
        bits = (ba // ch) * 8
      end
    elseif id == "data" then
      dpos, dlen = f:seek(), sz
      break
    else
      f:seek("cur", sz + (sz % 2))            -- riff chunks are word-aligned
    end
  end
  return afmt, ch, bits, sr, dpos, dlen
end

-- one sample decoder per (format, bit depth), each returning -1..1. 16/24/32-bit
-- PCM and 32-bit float are what norns itself can produce (the engine's take
-- dump, the system tape's print), and 8-bit is what old sample packs carry. ONE table: the waveform preview and the sample-rate converter below
-- read the same files, and a second copy would mean a format could draw
-- correctly and convert to noise, or the reverse.
local DECODE = {
  [1] = {
    -- 8-bit WAV is UNSIGNED, centred on 128 (the lo-fi and vintage packs)
    [8] = function(s, p) return (s:byte(p) - 128) / 128 end,
    [16] = function(s, p) return string.unpack("<i2", s, p) / 32768 end,
    [24] = function(s, p) return string.unpack("<i3", s, p) / 8388608 end,
    [32] = function(s, p) return string.unpack("<i4", s, p) / 2147483648 end,
  },
  [3] = {
    [32] = function(s, p) return string.unpack("<f", s, p) end,
  },
}

-- the decoder for a format/depth, or nil (callers read nil as "no preview" /
-- "refuse to convert" rather than drawing or writing a lie). riff_parse has
-- already resolved an extensible header to its real format.
local function wav_decoder(afmt, bits)
  return DECODE[afmt] and DECODE[afmt][bits]
end

-- open `path` and queue an async fill of `bins`: 128 peak bins spanning
-- `secs` seconds, so a file shorter than the span occupies only its share of
-- the strip (the engine clamps its reads the same way — a longer file only
-- occupies `secs` of the buffer, and drawing more would misalign every
-- playhead and slice). supersedes any queued fill of the SAME bins table.
-- returns the seconds the file occupies, or nil for a format the shared
-- decoders cannot read (the caller leaves the strip alone rather than lie).
function M.queue_fill(path, bins, secs)
  M.cancel_fill(bins)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, _, dpos, dlen = riff_parse(f)
  if not afmt then f:close(); return nil end
  local readpeak = wav_decoder(afmt, bits)
  if not dpos or ch < 1 or not readpeak then
    f:close()
    return nil
  end
  local bps = bits // 8
  local fbytes = ch * bps
  local SR = SERVER_SR
  local frames = min(floor(dlen / fbytes), floor(SR * secs))
  local span = clamp(frames / (SR * secs), 0, 1)
  local nbins = #bins > 0 and #bins or 128      -- an empty strip is a 128-bin one
  local nb = max(1, floor(span * nbins + 0.5))
  -- hand the slow per-bin peak read to load_tick (below). stride the UNPACKS
  -- (not the disk read) so a transient is never skipped — a 40ms drum hit
  -- vanished when this sampled a few windows per bin instead.
  local stride = max(1, floor(frames * ch / 200000))
  -- the stride counts SAMPLES of interleaved audio: an even stride over
  -- stereo lands on the left channel every time, and a right-only hit never
  -- drew. An odd one alternates.
  if ch > 1 and stride % ch == 0 then stride = stride + 1 end
  if frames > 0 then
    fills[#fills + 1] = { f = f, dpos = dpos, fbytes = fbytes, frames = frames,
      nb = nb, bps = bps, step = stride * bps, readpeak = readpeak, i = 0,
      bins = bins, per = BINS_PER_TICK * max(1, nbins // 128) }
  else
    f:close()
  end
  return frames / SR
end

-- fill up to BINS_PER_TICK bins of the queue's HEAD per call (driven by the
-- redraw clock), then close its file and move on. bounded work per frame →
-- the reads never block the UI; each strip draws IN over ~nb/10 frames.
function M.load_tick()
  local p = fills[1]
  if not p then return end
  local bins = p.bins
  -- a finer strip fills more bins a tick, so it draws in over the same time
  local last = min(p.i + p.per, p.nb)
  for i = p.i + 1, last do
    local b0 = floor((i - 1) / p.nb * p.frames)
    local n = floor(i / p.nb * p.frames) - b0
    local peak = 0
    if n > 0 then
      p.f:seek("set", p.dpos + b0 * p.fbytes)
      local chunk = p.f:read(n * p.fbytes)
      if chunk then
        for pp = 1, #chunk - (p.bps - 1), p.step do
          -- magnitude: the decoder is signed, the strip wants height
          local v = p.readpeak(chunk, pp)
          if v < 0 then v = -v end
          if v > peak then peak = v end
        end
      end
    end
    bins[i] = peak > 1 and 1 or peak
  end
  p.i = last
  if p.i >= p.nb then p.f:close(); table.remove(fills, 1) end
end

-- cancel EVERY in-flight fill (script cleanup)
function M.cancel_load() cancel_all_fills() end

-- ============================================================================
-- sample-rate conversion
-- ============================================================================
-- scsynth's Buffer:readChannel does NO sample-rate conversion and norns runs
-- its server at 48k, so a 44.1k wav — which is most of dust/audio and nearly
-- everything off a card — lands in the take buffer playing 8.8% fast, a
-- semitone and change sharp, with every pad, slice and window inheriting the
-- error. This converts a file to the server rate first.
--
-- It is deliberately here in lua and not in the engine: no new SC command, no
-- fingerprint change, no restart, and it yields so the screen stays live.
-- To change a file's sample rate you have to work out what the signal was
-- doing BETWEEN the samples you have. The shape used to do that is the whole
-- quality question. The simple choice is a cubic curve through four
-- neighbouring samples, which is what a sampler uses for varispeed; it is
-- cheap and it filters nothing.
--
-- Filtering nothing is the problem when converting DOWNWARDS. A 96k file can
-- hold sound up to 48 kHz, and 48k can only hold up to 24 kHz. Anything above
-- that has to be REMOVED first, or it does not disappear: it comes back
-- mirrored into the audible range as a tone that was never in the file. A
-- cubic curve leaves it all there. This shape removes it.
--
-- It is built once per conversion and stored as a table of numbers, so the
-- inner loop is lookups and multiplies rather than trigonometry. Measured at
-- 1.9x the cost of the cubic it replaces (ten seconds of 44.1k stereo: 0.68s
-- against 0.37s on a dev Mac). An import happens once, it already yields to
-- keep the screen alive, and a library converted ahead of time never gets
-- here at all.
local SINC_TAPS = 16          -- samples looked at per output sample; more
                              -- are used when converting downwards
local SINC_PHASES = 512       -- how finely we can land between two samples.
                              -- 1/512 of a sample off is inaudible

-- `cutoff` says how much of the sound has to survive. Converting UP, the
-- source file is the limit and nothing needs removing, so it is 1. Converting
-- DOWN, the new rate is the limit, so it is the ratio between them, and
-- everything above that has to go. Skip this and the mirrored-back tones are
-- the loudest thing in the converted file.
local function build_sinc(cutoff)
  local pi = math.pi
  local half = max(2, floor(SINC_TAPS / 2 / cutoff + 0.5))
  local taps = half * 2
  local k = {}
  for ph = 0, SINC_PHASES - 1 do
    local frac = ph / SINC_PHASES
    local base = ph * taps
    local sum = 0
    for t = 0, taps - 1 do
      local x = (t - half + 1) - frac         -- distance in SOURCE samples
      local a = pi * cutoff * x
      local s = (abs(a) < 1e-9) and cutoff or (cutoff * sin(a) / a)
      -- Taper the ends of the shape smoothly to zero (a Blackman window), or
      -- chopping it off at 16 samples rings.
      -- Measured on a 96k to 48k conversion, as how loud a tone comes back
      -- when it can only get through by being mirrored: 26k -13 dB, 30k
      -- -40 dB, 36k -75 dB, 40k -85 dB. The cubic left all four at -0.2 dB.
      -- So it takes until roughly half again above the limit to get really
      -- quiet, which is what 16 samples buys. What does leak through lands at
      -- 22 kHz and up, where the cubic was dropping the lot into the middle
      -- of the music.
      local u = (x + half) / taps
      s = s * (0.42 - 0.5 * cos(2 * pi * u) + 0.08 * cos(4 * pi * u))
      k[base + t + 1] = s
      sum = sum + s
    end
    -- Make each set of numbers add up to exactly 1. Otherwise each one
    -- amplifies very slightly differently, and since we cycle through them as
    -- we go, that is a volume wobble at the rate we cycle. It is an audible
    -- whine, not a rounding error.
    if sum ~= 0 then
      for t = 1, taps do k[base + t] = k[base + t] / sum end
    end
  end
  return k, half, taps
end

-- open a file for random-access frame reads. nil for anything we cannot
-- decode, so a caller refuses rather than working on silence.
local function open_src(path)
  local f = io.open(path, "rb")
  if not f then return nil, "cannot open " .. tostring(path) end
  local afmt, ch, bits, sr, dpos, dlen = riff_parse(f)
  local dec = afmt and wav_decoder(afmt, bits)
  if not (dec and dpos and ch and ch >= 1 and sr and sr > 0) then
    f:close(); return nil, "unsupported format"
  end
  local bps = bits // 8
  local fbytes = ch * bps
  return { f = f, dpos = dpos, ch = ch, bps = bps, fbytes = fbytes, sr = sr,
           dec = dec, frames = floor(dlen / fbytes), path = path }
end

local function close_src(s) if s and s.f then s.f:close(); s.f = nil end end

-- read n frames from `from` into L/R (1-based), zero-padding outside the file
-- so an interpolator may always ask for a neighbour it cannot have.
local function read_frames(src, from, n, L, R)
  local a, b = max(from, 0), min(from + n, src.frames)
  for i = 1, a - from do L[i], R[i] = 0, 0 end
  for i = max(1, b - from + 1), n do L[i], R[i] = 0, 0 end
  if b <= a then return end
  src.f:seek("set", src.dpos + a * src.fbytes)
  -- a file can be SHORTER than its header claims (a truncated copy, an
  -- interrupted write): a short read must still honour the zero-pad contract
  -- above, or a caller indexes nil exactly where the data chunk lied
  local chunk = src.f:read((b - a) * src.fbytes) or ""
  local dec, ch, bps, fb = src.dec, src.ch, src.bps, src.fbytes
  local o = a - from
  local got = #chunk // fb
  for i = 0, got - 1 do
    local p = i * fb + 1
    local l = dec(chunk, p)
    L[o + i + 1] = l
    R[o + i + 1] = ch > 1 and dec(chunk, p + bps) or l
  end
  for i = o + got + 1, b - from do L[i], R[i] = 0, 0 end
end

-- the converted file is written at 24 BITS. It is the last stop before the
-- engine buffer, and writing 16 threw away the bottom 8 bits of every 24-bit
-- source before it ever got there: a conversion that fixed the pitch and
-- quietly cost the depth.
local SRC_BLOCK = 4096
local SRC_BITS = 24
local SRC_BYTES = SRC_BITS // 8
local SRC_PEAK = 8388607
local SRC_PACK = "<" .. string.rep("i3", SRC_BLOCK * 2)

-- channels, duration and declared rate of a wav, from the header alone. nil
-- for anything that is not a readable RIFF/WAVE: the loaders then load it as
-- it is (no conversion, stereo, the whole region) rather than guessing.
function M.wav_info(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, sr, _, dlen = riff_parse(f)
  f:close()
  if not afmt or not sr or sr <= 0 or not ch or ch < 1 then return nil end
  local dur = (dlen and dlen > 0 and bits and bits > 0)
    and dlen / (ch * (bits / 8) * sr) or nil
  return ch, dur, sr
end

-- returns true, seconds  — converted and written to out_path
--         false, seconds — already at `sr`, nothing written
--         nil, err       — could not decode (the caller falls back to loading
--                          the file as-is: audible-but-sharp beats silence),
--                          or `yield` returned false ("cancelled")
function M.convert_sr(path, out_path, sr, yield, max_secs)
  local src, err = open_src(path)
  if not src then return nil, err end
  local in_sr, frames = src.sr, src.frames
  if frames < 2 then close_src(src); return nil, "no audio" end
  -- refuse an implausible declared rate HERE, not just via the caller's cap:
  -- a corrupt header claiming 1 Hz turns a 4800-frame file into 230M output
  -- frames, and an opt-in cap is protection a future caller forgets (the
  -- caller falls back to loading the file as-is, which is bounded)
  if in_sr < 4000 or in_sr > 384000 then
    close_src(src); return nil, "implausible sample rate " .. tostring(in_sr)
  end
  if in_sr == sr then close_src(src); return false, frames / sr end

  local of = io.open(out_path, "wb")
  if not of then close_src(src); return nil, "cannot write " .. tostring(out_path) end
  -- header with placeholder sizes, backpatched at the end
  of:write("RIFF", string.pack("<I4", 36), "WAVE")
  local obytes = SRC_BYTES * 2                    -- bytes per stereo frame
  of:write("fmt ", string.pack("<I4", 16), string.pack("<I2", 1),
    string.pack("<I2", 2), string.pack("<I4", sr),
    string.pack("<I4", sr * obytes),
    string.pack("<I2", obytes), string.pack("<I2", SRC_BITS))
  of:write("data", string.pack("<I4", 0))

  local ratio = in_sr / sr
  local kern, half, taps = build_sinc(min(1, sr / in_sr))
  local out_n = floor(frames / ratio)
  -- bound the OUTPUT, not just the input: the take buffer only holds max_secs
  -- anyway, and without this a corrupt header declaring a tiny rate expands a
  -- small file into gigabytes (4800 frames at a claimed 1 Hz = 921 MB out) —
  -- while a long DJ mix converts minutes of audio the buffer would discard
  if max_secs then out_n = min(out_n, floor(sr * max_secs)) end
  local L, R = {}, {}
  local out_v = {}
  local written = 0
  while written < out_n do
    local bn = min(SRC_BLOCK, out_n - written)
    local p0 = written * ratio
    local p1 = (written + bn - 1) * ratio
    local lo = floor(p0) - half
    local hi = floor(p1) + half + 1
    read_frames(src, lo, hi - lo + 1, L, R)
    for k = 0, bn - 1 do
      local pos = (written + k) * ratio
      local ip = floor(pos)
      local ph = floor((pos - ip) * SINC_PHASES)
      if ph >= SINC_PHASES then ph = SINC_PHASES - 1 end
      local base = ph * taps
      -- tap t reads source frame ip + t - half + 1; the kernel is even, so
      -- the same coefficient serves both sides of the output position
      local j = ip - lo - half + 2
      local vl, vr = 0, 0
      for t = 0, taps - 1 do
        local c = kern[base + t + 1]
        vl = vl + c * (L[j + t] or 0)
        vr = vr + c * (R[j + t] or 0)
      end
      vl = vl * SRC_PEAK
      if vl > SRC_PEAK then vl = SRC_PEAK elseif vl < -SRC_PEAK then vl = -SRC_PEAK end
      vr = vr * SRC_PEAK
      if vr > SRC_PEAK then vr = SRC_PEAK elseif vr < -SRC_PEAK then vr = -SRC_PEAK end
      out_v[k * 2 + 1] = floor(vl + 0.5)
      out_v[k * 2 + 2] = floor(vr + 0.5)
    end
    local fmt = bn == SRC_BLOCK and SRC_PACK or ("<" .. string.rep("i3", bn * 2))
    of:write(string.pack(fmt, table.unpack(out_v, 1, bn * 2)))
    written = written + bn
    -- every block: with the sinc kernel one block is 16 to 64 taps per output
    -- sample, tens of ms on a Mac and several times that on a Pi, and a yield
    -- (clock.sleep(0)) costs nothing next to it. Every 4 blocks was a cadence
    -- sized for the old 4-tap cubic, and it froze the screen in jerks.
    -- A yield that returns false cancels: the caller no longer wants the
    -- result, so the files close and the part-written output goes.
    if yield and yield() == false then
      close_src(src); of:close(); os.remove(out_path)
      return nil, "cancelled"
    end
  end

  local datalen = written * obytes
  of:seek("set", 4);  of:write(string.pack("<I4", 36 + datalen))
  of:seek("set", 40); of:write(string.pack("<I4", datalen))
  close_src(src); of:close()
  return true, written / sr
end

-- WHERE THE SOUND ACTUALLY IS. Returns the first and last positions above a
-- threshold, as fractions of a `buf_secs` buffer — the same units the window
-- uses. nil when the file cannot be read, or when nothing clears the floor
-- (silence), so a caller can tell "nothing there" from "could not look".
--
-- The point: pressing REC and then playing leaves your reaction time at the
-- head of every take, and letting go late leaves room tone at the tail. The
-- rec-stop window snaps to where the HEADS were, not to where the sound is.
function M.onset_bounds(path, from01, to01, buf_secs, thresh, yield)
  local src, err = open_src(path)
  if not src then return nil, err end
  local total = floor(buf_secs * src.sr)
  local from = clamp(floor(from01 * total), 0, src.frames)
  local to = clamp(floor(to01 * total), 0, src.frames)
  if to - from < 64 then close_src(src); return nil, "range is empty" end
  thresh = thresh or 0.004                       -- about -48 dBFS
  local L, R = {}, {}
  local CH = 8192
  local first, last = nil, nil
  local i = from
  while i < to do
    local n = min(CH, to - i)
    read_frames(src, i, n, L, R)
    for k = 1, n do
      local a = abs(L[k]); local b = abs(R[k])
      if a > thresh or b > thresh then
        if not first then first = i + k - 1 end
        last = i + k - 1
      end
    end
    i = i + n
    if yield then yield() end
  end
  close_src(src)
  if not first then return nil, "silence" end
  return first / total, (last + 1) / total
end

-- TRANSIENT DETECTION: where does the material actually start hitting?
-- A 10ms energy envelope; an onset is where energy jumps against its neighbour
-- and clears a floor. Energy tolerates a strided decode (a transient is
-- milliseconds wide, i.e. hundreds of frames), so only every 8th frame of a
-- window is decoded at all: decoding them all and then skipping seven of
-- eight spent most of a CHOP on samples the envelope never read.
--
-- `from01`/`to01` bound the search as fractions of a `buf_secs` buffer, and the
-- cuts come back in the same units — so a caller works in the window's own
-- coordinates and never has to know the file's rate or length.
-- Returns nil (not an empty list) when the file cannot be read, so a caller can
-- tell "no transients here" from "could not look".
function M.transient_cuts(path, from01, to01, maxn, buf_secs, yield)
  local src, err = open_src(path)
  if not src then return nil, err end
  local total = floor(buf_secs * src.sr)
  local from = clamp(floor(from01 * total), 0, src.frames)
  local to = clamp(floor(to01 * total), 0, src.frames)
  if to - from < 64 then close_src(src); return nil, "range is empty" end

  local win = max(64, floor(src.sr * 0.01))
  local stride = 8
  local env = {}
  local dec, fb, bps, stereo = src.dec, src.fbytes, src.bps, src.ch > 1
  local i, k = from, 0
  while i < to do
    local n = min(win, to - i)
    src.f:seek("set", src.dpos + i * fb)
    local chunk = src.f:read(n * fb) or ""   -- short read = the file lied: zeros
    local got = #chunk // fb
    local e = 0
    for j = 0, got - 1, stride do
      local p = j * fb + 1
      local l = abs(dec(chunk, p))
      local a = l + (stereo and abs(dec(chunk, p + bps)) or l)
      if a > e then e = a end
    end
    k = k + 1
    env[k] = e * 0.5
    i = i + n
    if yield and (k % 32 == 0) then yield() end
  end
  close_src(src)

  -- floor: a fraction of the loudest window, so quiet material still chops and
  -- room tone does not
  local peak = 0
  for j = 1, k do if env[j] > peak then peak = env[j] end end
  local floorlv = peak * 0.18
  local hits = {}
  local last = -99
  for j = 2, k do
    local prev = env[j - 1]
    if env[j] > floorlv and env[j] > prev * 2.2 and (j - last) > 3 then
      last = j
      hits[#hits + 1] = (from + (j - 1) * win) / total
    end
  end
  -- the first slice always starts at the edge. More hits than pads: take them
  -- evenly across the whole take. Stopping at the first few gave the last pad
  -- most of the take (the device: 3.5s of a 6s drum loop).
  local cuts = { from01 }
  local room = maxn - 1
  for c = 1, math.min(#hits, room) do
    local at = #hits <= room and c or floor((c - 1) * #hits / room) + 1
    cuts[#cuts + 1] = hits[at]
  end
  return cuts
end

-- interleave two MONO wavs (the L/R pair write_take dumps) into one stereo
-- wav. A browsable export that reloads via load sample, ZERO new load code.
-- Lua-only (no engine interleave). Returns true on success.
--
-- The samples are spliced as BYTES and the depth is read from the header, so
-- this follows whatever the engine wrote rather than pinning the export to a
-- depth of its own. write_take moved to 24-bit; this needed no other change.
local function open_pcm_mono(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, sr, dpos, dlen = riff_parse(f)
  if not dpos or afmt ~= 1 or ch ~= 1 or not bits
      or (bits ~= 16 and bits ~= 24 and bits ~= 32) then
    f:close(); return nil
  end
  local bps = bits // 8
  f:seek("set", dpos)
  return f, floor(dlen / bps), sr, bps   -- handle, frames, rate, bytes/sample
end

function M.interleave_wav(pathL, pathR, out, yield)
  local fL, nL, sr, bps = open_pcm_mono(pathL)
  if not fL then return false end
  local fR, nR, _, bpsR = open_pcm_mono(pathR)
  if not fR then fL:close(); return false end
  -- a mismatched pair is not a stereo file: refuse rather than interleave
  -- samples of two different widths into a header that can only claim one
  if bpsR ~= bps then fL:close(); fR:close(); return false end
  local frames = min(nL, nR)
  local of = io.open(out, "wb")
  if not of then fL:close(); fR:close(); return false end
  local fb = bps * 2                              -- bytes per stereo frame
  local datalen = frames * fb
  of:write("RIFF", string.pack("<I4", 36 + datalen), "WAVE")
  of:write("fmt ", string.pack("<I4", 16), string.pack("<I2", 1), string.pack("<I2", 2),
    string.pack("<I4", sr), string.pack("<I4", sr * fb), string.pack("<I2", fb),
    string.pack("<I2", bps * 8))
  of:write("data", string.pack("<I4", datalen))
  local CHUNK = 8192                               -- frames per pass
  -- unpack each mono chunk as integers and pack them back interleaved: two
  -- string.sub calls per frame made millions of short strings for the GC
  local code = "i" .. bps
  local mono_full = "<" .. string.rep(code, CHUNK)
  local st_full = "<" .. string.rep(code, CHUNK * 2)
  local out = {}
  local i, since = 0, 0
  while i < frames do
    local n = min(CHUNK, frames - i)
    local lc, rc = fL:read(n * bps), fR:read(n * bps)
    if not lc or not rc or #lc < n * bps or #rc < n * bps then break end
    local mono = n == CHUNK and mono_full or ("<" .. string.rep(code, n))
    local lv = { string.unpack(mono, lc) }
    local rv = { string.unpack(mono, rc) }
    for k = 1, n do out[2 * k - 1] = lv[k]; out[2 * k] = rv[k] end
    of:write(string.pack(n == CHUNK and st_full or ("<" .. string.rep(code, n * 2)),
      table.unpack(out, 1, n * 2)))
    i = i + n
    since = since + 1
    if yield and since >= 2 then since = 0; yield() end   -- ~16k frames / yield
  end
  -- a short read means the declared header over-states the data; backpatch the
  -- RIFF + data sizes to what we actually wrote so the wav isn't malformed.
  if i < frames then
    local dl = i * fb
    of:seek("set", 4); of:write(string.pack("<I4", 36 + dl))
    of:seek("set", 40); of:write(string.pack("<I4", dl))
  end
  fL:close(); fR:close(); of:close()
  return true
end

return M

end)()
local Mpages = (function()  -- inlined lib/mpages.lua
-- mpages: the screen — the wave/twave display models, every page body, the
-- header, the footer, and the redraw composition.
--   header y0..8   the page title (1x), the purity mark, the write/hold flags,
--                  the page dots top-right
--   body   y11..53 one dominant object per page, drawn from real state
--   footer y56..63 four quiet words: K2 K3 | E2 E3. a turning knob brightens
--                  its word and swells its value in a framed 2x box just above
--                  the footer, bottom right, for ~1.2s
-- The strips are painted from files through lib/mwav.lua (lua cannot read an
-- SC or softcut buffer); this module owns the strips, mwav reads the files.

local floor, sin, cos = math.floor, math.sin, math.cos
local abs, sqrt, min, max = math.abs, math.sqrt, math.min, math.max
local log, exp, PI = math.log, math.exp, math.pi

local C     -- shared ctx, bound at init
local W     -- lib/mwav (the file reader), handed in through ctx.wav
local pget, clamp, window_bounds, FPS, PAGES
local ptext, ptext_c, ptext_r, chip, text_w
local amp_in, amp_out

-- waveform display: 128 amplitude bins over the buffer, filled as the write
-- head passes; pre_level decides how much of the old picture survives overdub
-- (four) one strip per track, its own material; `wave` is the focused
-- track's, swapped by M.focus_wave
local waves = {}
for n = 1, 4 do
  waves[n] = {}
  for i = 1, 128 do waves[n][i] = 0 end
end
local wave = waves[1]
local wave_bin = 0

-- same idea for the tape loop: bins indexed by the tape head while recording
-- A loop deck (the tape) keeps a FINER picture than the
-- take: 1024 bins over their 60s, 59ms each. A deck page zooms onto the loop,
-- and a 4s loop was 8 bins of the old 128: it never looked recorded.
local DECK_BINS = 1024
local twave = {}
for i = 1, DECK_BINS do twave[i] = 0 end
local twave_bin = 0

-- paint amplitude into display bins between the last-seen head position and
-- the current one, walking the SHORTER way around the (circular) buffer —
-- so bins skipped between frames at high rates get filled, wrap-around is
-- seamless, and reverse playback paints in the right direction. entering a
-- fresh bin, previous content survives by `pre` (the overdub picture).
-- A JUMP is not a walk: no head travels more than a bin per frame (the
-- fastest, a deck at 4x, moves about 0.6), so a gap of several bins is a
-- loop wrapping round or a pass re-armed somewhere else. Walking it painted
-- the whole loop with one moment's level (every seam of a DUB loop drew a
-- solid block). Only the landing bin is painted.
-- JUMP_BINS is for a strip of 128 bins; a finer strip scales it, so a jump
-- is the same stretch of time on every strip.
local JUMP_BINS = 3
local function paint_bins(bins, last, bin, amp, pre)
  if last == 0 or last == bin then
    bins[bin] = max(bins[bin], amp)
    return bin
  end
  local n = #bins
  local jump = JUMP_BINS * n / 128
  local fwd = (bin - last) % n
  local bwd = (last - bin) % n
  if fwd > jump and bwd > jump then
    bins[bin] = max(bins[bin] * pre, amp)
    return bin
  end
  local step = (fwd <= bwd) and 1 or -1
  local b = last
  repeat
    b = ((b - 1 + step) % n) + 1
    bins[b] = max(bins[b] * pre, amp)
  until b == bin
  return bin
end
local M = {}
M.paint_bins = paint_bins   -- a deck paints its own picture (lib/mdeck.lua)
M.DECK_BINS = DECK_BINS

-- track the buffer's contents as the write head passes over it. STOP holds
-- the record head (an arm under STOP waits for START), so it holds the
-- picture too: painting the live input over a head that writes nothing set
-- wave_any over an empty buffer, and the next PSET save wrote 60s of silence.
function M.update_wave()
  if pget("rec", 0) == 1 and pget("freeze", 0) == 0
      and pget("stop_all", 0) == 0 then
    local bin = floor(clamp(C.rec_phase, 0, 0.999) * 128) + 1
    if C.rec_amp > 0.01 then C.wave_any = true end
    wave_bin = paint_bins(wave, wave_bin, bin, C.rec_amp, pget("pre_level", 0))
  end
end

-- track the tape loop's contents as the head records (input amplitude,
-- since softcut exposes no per-voice output meter); tape_pre sets survival
function M.update_tape_wave()
  if pget("tape_rec", 0) == 1 and pget("tape_freeze", 0) == 0
      and pget("stop_all", 0) == 0 then
    local bin = floor(clamp(C.tape_phase, 0, 0.999) * DECK_BINS) + 1
    -- meter what softcut actually records (C.cut_rec_amp — the ADC tap, the
    -- engine output, or the blend): a WET print otherwise painted nothing
    -- and left twave_any false over audible tape
    local a = C.cut_rec_amp()
    if a > 0.01 then
      C.twave_any = true
      C.tape_heard, C.tape_quiet = true, 0
    else
      -- silence at the source: TAPE says so after a second of it
      C.tape_quiet = (C.tape_quiet or 0) + 1
    end
    twave_bin = paint_bins(twave, twave_bin, bin, a, pget("tape_pre", 0))
  else
    C.tape_quiet = 0
  end
end

-- wipe ANY strip, cancelling its own queued repaint
function M.clear_bins(bins)
  W.cancel_fill(bins)
  for i = 1, #bins do bins[i] = 0 end
end

-- wipe the tape picture (the CLR gesture starts the loop over)
function M.clear_twave()
  M.clear_bins(twave)
  twave_bin = 0
  C.twave_any = false
end

-- wipe the engine's picture (the engine `clear` command): the buffer is gone, so the strip
-- must go with it — every page that draws the take goes back to inviting one.
-- the focus moved to track n: its strip becomes the one TAKE draws and the
-- record head paints
function M.focus_wave(n)
  wave = waves[n] or waves[1]
  wave_bin = 0
end
-- track n's strip, for a restore that lands while another track is focused
function M.track_wave(n) return waves[n] end

function M.clear_wave()
  M.clear_bins(wave)  -- stops an in-flight TAKE fill first
  wave_bin = 0
  C.wave_any = false
end

-- the TAKE's preview: clear the strip FIRST, so an unsupported-format /
-- unreadable early return leaves a flat strip instead of the previous take's
-- waveform; a 24-bit drop-in draws + windows correctly via the shared decoder
-- (the bug this once had for everything except 16-bit).
function M.load_wave(path, buf_secs)
  for i = 1, 128 do wave[i] = 0 end
  wave_bin = 0
  local dur = W.queue_fill(path, wave, buf_secs)
  if dur ~= nil then C.wave_any = dur > 0 end
  return dur
end

-- fill an ARBITRARY strip from a wav: a track's strip or the tape's, when a
-- pset restores its audio (lua cannot read the
-- softcut buffer, but the wav it was restored FROM is right there; without
-- this a restored loop played audibly under a blank picture).
function M.fill_wave_bins(path, bins, secs)
  -- a strip that is still empty becomes a 128-bin one
  for i = 1, (#bins > 0 and #bins or 128) do bins[i] = 0 end
  return W.queue_fill(path, bins, secs)
end

-- repaint the TAKE's strip from a dump of the buffer, leaving the window and
-- wave_any alone: the material is the same take, changed in place by regen
-- or erosion
function M.repaint_wave(path)
  wave_bin = 0
  return M.fill_wave_bins(path, wave, C.BUF_SECS)
end

-- the tape strip's version of the same (mpages owns twave)
function M.repaint_twave(path, secs)
  twave_bin = 0
  return M.fill_wave_bins(path, twave, secs)
end

-- deterministic dither, same trick as the mockups
local function hash(x, y, sd)
  local f = sin(x * 12.9898 + y * 78.233 + sd * 37.719) * 43758.5453
  return f - floor(f)
end

-- a waveform LANE: the 128 bins of `bins` stretched across columns x0..x1 as
-- vertical strokes around the centre row ym. The height law is the one every
-- strip shares: sqrt so quiet material still reads, times `k`, clamped to
-- [hmin, hmax]. `lo`/`span` (default the whole strip) zoom it onto a part of
-- the bins, which is how PADS draws only the window. The caller sets the level.
local function wave_lane(bins, x0, x1, ym, k, hmin, hmax, lo, span)
  lo, span = lo or 0, span or 1
  local n = #bins
  local w = x1 - x0
  local per = span * (n - 1) / w        -- bins for each column
  for x = x0, x1 do
    local i0 = floor((lo + (x - x0) / w * span) * (n - 1)) + 1
    local a = bins[i0] or 0
    -- a column that covers several bins shows the loudest of them, or a
    -- short hit between two columns would not draw
    if per > 1 then
      for i = i0 + 1, min(n, floor(i0 + per)) do
        local b = bins[i]
        if b > a then a = b end
      end
    end
    if a > 0.002 then
      local h = clamp(sqrt(min(a * 2, 1)) * k, hmin, hmax)
      screen.move(x, ym - h)
      screen.line(x, ym + h)
    end
  end
  screen.stroke()
end

-- WHAT A DECK STRIP SHOWS. A deck is 60s long and a loop is a few seconds of
-- it, so a strip of the whole deck drew a loop as a sliver. The strip shows:
--   the LOOP, when one is set (its two ends are the strip's two ends);
--   else the MATERIAL (a first pass that is still open: from where it began,
--   8s at least, so the pass fills the strip from the left as it records);
--   else the whole deck.
-- Returns lo and span (0..1 of the deck).
local function deck_view(ls, le, mat_lo, mat_hi, len)
  local lo, hi = min(ls, le), max(ls, le)
  if hi - lo < 0.999 then return lo, max(hi - lo, 0.0001) end
  if mat_lo and mat_hi then
    local span = max(mat_hi - mat_lo, 8 / len)
    if mat_lo + span > 1 then span = 1 - mat_lo end
    return mat_lo, max(span, 0.0001)
  end
  return 0, 1
end

-- where the strip sits in the whole deck: a rail one pixel high with the
-- shown stretch lit. Drawn only when the strip is a part of the deck.
local function view_map(x0, x1, y, lo, span, lvl)
  if span > 0.98 then return end
  local w = x1 - x0
  screen.level(1)
  screen.rect(x0, y, w + 1, 1)
  screen.fill()
  screen.level(lvl)
  screen.rect(x0 + floor(lo * w), y, max(2, floor(span * w + 0.5)), 1)
  screen.fill()
end

-- the head on a zoomed strip, or nil when it is outside the strip
local function view_x(ph, x0, x1, lo, span)
  local t = (ph - lo) / span
  if t < 0 or t > 1 then return nil end
  return x0 + floor(t * (x1 - x0))
end

-- the record-SOURCE flag: what a pass records is never a hidden mode. WET
-- (the default: what four plays) reads dim. A blend and DRY (the line input
-- alone) read bright. Reads the EFFECTIVE source.
local function src_flag(x, y)
  local src = C.eff_cut_source()
  if src > 0.98 then
    ptext("SRC WET", x, y, 1, 5)
  elseif src < 0.02 then
    ptext("SRC DRY", x, y, 1, 9)
  else
    ptext("SRC WET " .. floor(src * 100 + 0.5) .. "%", x, y, 1, 9)
  end
end

-- the framed 2x readout: black pocket, level-12 frame, the text at 2x. The
-- turning knob's value and the page-name pop both use it, so it is legible
-- over any body.
local function framed2x(str, bx, y)
  local w = text_w(str, 2) + 9
  screen.level(0)
  screen.rect(bx, y, w + 2, 15)
  screen.fill()
  screen.level(12)
  screen.rect(bx, y, w + 2, 15)
  screen.stroke()
  ptext(str, bx + 5, y + 3, 2, 15)
end

